SAVE_DIR="./build/tests/functional/work-$$/homes/attach-$$"
mkdir -p "$SAVE_DIR"
SAVE_OUT=$( (export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME;
