ACCS=$( (export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME;
    "$BIN_DIR/email-cli" --batch list-accounts 2>&1 || true) )
check "18.1 list-accounts: account listed"  "alpha@test.local"  "$ACCS"
