if phase_wanted 22; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 22 — Credential obfuscation
#
# User Stories:
#   US-01  Default: fresh account config is saved with "enc:" prefix
#   US-02  Encrypted config loads and authenticates successfully
#   US-03  Plaintext config (legacy / obfuscation disabled) loads correctly
#   US-04  migrate-credentials converts plaintext → encrypted
#   US-05  Disable obfuscation + migrate converts encrypted → plaintext
#   US-06  Re-enable obfuscation + migrate converts plaintext → encrypted again
#   US-07  Two accounts with the same password produce different enc: values
#   US-08  migrate-credentials is idempotent (double-run safe)
#   US-09  Absent settings.ini defaults to obfuscation ON
#   US-10  Auto-encrypt on load (no migrate needed): plain→enc on first access
#   US-11  Auto-decrypt on load (no migrate needed): enc→plain on first access
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 22: credential obfuscation ---"

# Isolated home for obfuscation tests (no mock server needed for format checks)
H_CRED="./build/tests/functional/work-$$/homes/cred-$$"
CRED_EMAIL="cred@test.local"
CRED_CFG="$H_CRED/.config/email-cli/accounts/$CRED_EMAIL/config.ini"
CRED_SETTINGS="$H_CRED/.config/email-cli/settings.ini"

# Helper: write a plaintext account config
make_cred_home() {
    rm -rf "./build/tests/functional/work-$$/homes/cred-$$"
    mkdir -p "$H_CRED/.config/email-cli/accounts/$CRED_EMAIL"
    cat > "$CRED_CFG" <<CFG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=$CRED_EMAIL
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CFG
}

# Helper: run email-cli with isolated HOME (no server contact needed for migration)
run_cred() {
    (export HOME="$H_CRED"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     "$BIN_DIR/email-cli" "$@" 2>&1 || true)
}

# ── US-09: No settings.ini → obfuscation defaults to ON ──────────────────
make_cred_home
# run migrate-credentials without a settings.ini
OUT_09=$(run_cred migrate-credentials)
check "22-US09: migrate without settings.ini reports encrypting" \
    "encrypt" "$OUT_09"
check "22-US09: config file has enc: prefix after default migrate" \
    "enc:" "$(cat "$CRED_CFG")"

# ── US-01: Default save produces enc: prefix ─────────────────────────────
# After migrate with default settings, the password field must have enc:
check "22-US01: EMAIL_PASS stored with enc: prefix" \
    "^EMAIL_PASS=enc:" "$(grep EMAIL_PASS "$CRED_CFG")"

# ── US-08: migrate-credentials is idempotent ─────────────────────────────
PASS_AFTER_FIRST=$(grep EMAIL_PASS "$CRED_CFG")
run_cred migrate-credentials > /dev/null
PASS_AFTER_SECOND=$(grep EMAIL_PASS "$CRED_CFG")
# The enc: prefix must still be present; the value may differ (new IV each time)
check "22-US08: idempotent — enc: still present after second migrate" \
    "^EMAIL_PASS=enc:" "$(grep EMAIL_PASS "$CRED_CFG")"

# ── US-02: Encrypted config loads and authenticates ──────────────────────
# Use the encrypted config to list emails via the mock IMAP server
OUT_02=$(run_list "$H_CRED" "" INBOX)
check "22-US02: encrypted config: list succeeds (AlphaAccountMsg)" \
    "AlphaAccountMsg" "$OUT_02"

# ── US-03: Plaintext config loads transparently ──────────────────────────
make_cred_home   # reset to plaintext
OUT_03=$(run_list "$H_CRED" "" INBOX)
check "22-US03: plaintext config: list succeeds (AlphaAccountMsg)" \
    "AlphaAccountMsg" "$OUT_03"

# ── US-04: migrate-credentials converts plaintext → encrypted ────────────
make_cred_home
# Confirm it is plaintext before migration
check_not "22-US04: before migrate — no enc: prefix" \
    "enc:" "$(cat "$CRED_CFG")"
run_cred migrate-credentials > /dev/null
check "22-US04: after migrate — enc: prefix present" \
    "enc:" "$(cat "$CRED_CFG")"
# And it must still authenticate
OUT_04=$(run_list "$H_CRED" "" INBOX)
check "22-US04: after migrate — list still works" \
    "AlphaAccountMsg" "$OUT_04"

# ── US-05: Disable obfuscation + migrate converts encrypted → plaintext ──
# Start from an encrypted config
make_cred_home
run_cred migrate-credentials > /dev/null
check "22-US05 setup: config is encrypted" \
    "enc:" "$(cat "$CRED_CFG")"
# Disable obfuscation
echo "credential_obfuscation=false" > "$CRED_SETTINGS"
OUT_05=$(run_cred migrate-credentials)
check "22-US05: migrate after disable reports removing encryption" \
    "plaintext" "$OUT_05"
check_not "22-US05: config no longer has enc: prefix" \
    "enc:" "$(cat "$CRED_CFG")"
check "22-US05: plaintext config still has the password value" \
    "EMAIL_PASS=testpass" "$(cat "$CRED_CFG")"
# Verify authentication still works
OUT_05b=$(run_list "$H_CRED" "" INBOX)
check "22-US05: after decrypt migrate — list still works" \
    "AlphaAccountMsg" "$OUT_05b"

# ── US-06: Re-enable obfuscation + migrate converts plaintext → encrypted ─
echo "credential_obfuscation=true" > "$CRED_SETTINGS"
run_cred migrate-credentials > /dev/null
check "22-US06: after re-enable — enc: prefix present again" \
    "enc:" "$(cat "$CRED_CFG")"
OUT_06=$(run_list "$H_CRED" "" INBOX)
check "22-US06: after re-encrypt — list still works" \
    "AlphaAccountMsg" "$OUT_06"

# ── US-07: Two accounts with the same password have different enc: values ─
H_DUAL="./build/tests/functional/work-$$/homes/dual-$$"
DUAL_A="dual-a@test.local"
DUAL_B="dual-b@test.local"
rm -rf "./build/tests/functional/work-$$/homes/dual-$$"
for ACCT in "$DUAL_A" "$DUAL_B"; do
    mkdir -p "$H_DUAL/.config/email-cli/accounts/$ACCT"
    cat > "$H_DUAL/.config/email-cli/accounts/$ACCT/config.ini" <<CFG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=$ACCT
EMAIL_PASS=samepassword
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CFG
done
(export HOME="$H_DUAL"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
 "$BIN_DIR/email-cli" migrate-credentials 2>&1 || true) > /dev/null
ENC_A=$(grep EMAIL_PASS "$H_DUAL/.config/email-cli/accounts/$DUAL_A/config.ini")
ENC_B=$(grep EMAIL_PASS "$H_DUAL/.config/email-cli/accounts/$DUAL_B/config.ini")
check "22-US07: both accounts have enc: prefix" \
    "enc:" "$ENC_A"
check "22-US07: both accounts have enc: prefix (B)" \
    "enc:" "$ENC_B"
if [ "$ENC_A" = "$ENC_B" ]; then
    echo "  [FAIL] 22-US07: two accounts with same password produced identical enc: values"
    FAILED=$((FAILED + 1))
else
    echo "  [PASS] 22-US07: different accounts → different enc: values (even with same password)"
    PASSED=$((PASSED + 1))
fi

# ── US-10: Auto-encrypt on load (no migrate needed) ──────────────────────
# Start from a plaintext config with obfuscation ON (default)
make_cred_home
check_not "22-US10: before any access — no enc: prefix" \
    "enc:" "$(cat "$CRED_CFG")"
# A plain list command triggers load → auto-encrypt
run_list "$H_CRED" "" INBOX > /dev/null
check "22-US10: after first access — enc: prefix auto-applied" \
    "enc:" "$(cat "$CRED_CFG")"
# Authentication still works after auto-encrypt
OUT_10=$(run_list "$H_CRED" "" INBOX)
check "22-US10: after auto-encrypt — list still works" \
    "AlphaAccountMsg" "$OUT_10"

# ── US-11: Auto-decrypt on load (no migrate needed) ──────────────────────
# Start from an encrypted config, then disable obfuscation
make_cred_home
run_cred migrate-credentials > /dev/null  # encrypt first
check "22-US11 setup: config is encrypted" \
    "enc:" "$(cat "$CRED_CFG")"
echo "credential_obfuscation=false" > "$CRED_SETTINGS"
# A plain list command triggers load → auto-decrypt
run_list "$H_CRED" "" INBOX > /dev/null
check_not "22-US11: after first access — enc: prefix auto-removed" \
    "enc:" "$(cat "$CRED_CFG")"
check "22-US11: plaintext password restored in config" \
    "EMAIL_PASS=testpass" "$(cat "$CRED_CFG")"
# Authentication still works after auto-decrypt
OUT_11=$(run_list "$H_CRED" "" INBOX)
check "22-US11: after auto-decrypt — list still works" \
    "AlphaAccountMsg" "$OUT_11"

# Cleanup isolated homes
rm -rf "./build/tests/functional/work-$$/homes/cred-$$" "./build/tests/functional/work-$$/homes/dual-$$"

fi

if phase_wanted 23; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 23 — Account selection on the command line
#
# User Stories:
#   US-01  Single account, no selector → works (backward compatible)
#   US-02  Multiple accounts + positional account arg → correct account used
#   US-03  Multiple accounts + --account flag → correct account used
#   US-04  Multiple accounts, no selector → helpful error listing accounts
#   US-05  email-cli-ro: positional account arg
#   US-06  email-cli-ro: --account flag
#   US-07  email-cli-ro: multiple accounts, no selector → error
#   US-08  Unknown account name → error
#   US-09  Positional account + help → shows help for command
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 23: account selection ---"

# ── US-01: Single account, no selector ───────────────────────────────────
OUT_23_01=$(run_list "$H_ALPHA" "")
check "23-US01: single account, no selector — AlphaAccountMsg" \
    "AlphaAccountMsg" "$OUT_23_01"

# ── US-02: Positional account arg in multi-account home ──────────────────
OUT_23_02A=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" "$ALPHA" list --batch 2>&1 || true)
check "23-US02: positional alpha → AlphaAccountMsg" \
    "AlphaAccountMsg" "$OUT_23_02A"

OUT_23_02B=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" "$BETA" list --batch 2>&1 || true)
check "23-US02: positional beta → BetaAccountMsg" \
    "BetaAccountMsg" "$OUT_23_02B"
check_not "23-US02: positional beta → not AlphaAccountMsg" \
    "AlphaAccountMsg" "$OUT_23_02B"

# ── US-03: --account flag in multi-account home ───────────────────────────
OUT_23_03=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" --account "$BETA" list --batch 2>&1 || true)
check "23-US03: --account beta → BetaAccountMsg" \
    "BetaAccountMsg" "$OUT_23_03"

# ── US-04: Multiple accounts, no selector → error ────────────────────────
OUT_23_04=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" list --batch 2>&1 || true)
check "23-US04: no selector error mentions alpha" \
    "$ALPHA" "$OUT_23_04"
check "23-US04: no selector error mentions beta" \
    "$BETA" "$OUT_23_04"

# ── US-05: email-cli-ro positional account ────────────────────────────────
OUT_23_05=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" "$BETA" list --batch 2>&1 || true)
check "23-US05: email-cli-ro positional beta → BetaAccountMsg" \
    "BetaAccountMsg" "$OUT_23_05"

# ── US-06: email-cli-ro --account flag ────────────────────────────────────
OUT_23_06=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --account "$ALPHA" list --batch 2>&1 || true)
check "23-US06: email-cli-ro --account alpha → AlphaAccountMsg" \
    "AlphaAccountMsg" "$OUT_23_06"

# ── US-07: email-cli-ro multiple accounts, no selector → error ───────────
OUT_23_07=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" list --batch 2>&1 || true)
check "23-US07: email-cli-ro no selector error mentions alpha" \
    "$ALPHA" "$OUT_23_07"

# ── US-08: Unknown account name → error ──────────────────────────────────
OUT_23_08=$(
    export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" "nobody@nowhere.invalid" list --batch 2>&1 || true)
check "23-US08: unknown account → error mentions account name" \
    "nobody@nowhere.invalid" "$OUT_23_08"

# ── US-09: Positional account + help shows command help ──────────────────
OUT_23_09=$(
    export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" "$ALPHA" help list 2>&1 || true)
check "23-US09: account + help list → shows list help" \
    "Usage:" "$OUT_23_09"

# ── US-10: list-accounts works without specifying an account ─────────────
OUT_23_10_ro=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" list-accounts 2>&1 || true)
check "23-US10: email-cli-ro list-accounts lists alpha" \
    "$ALPHA" "$OUT_23_10_ro"
check "23-US10: email-cli-ro list-accounts lists beta" \
    "$BETA" "$OUT_23_10_ro"

OUT_23_10_rw=$(
    export HOME="$H_AB"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" list-accounts 2>&1 || true)
check "23-US10: email-cli list-accounts lists alpha" \
    "$ALPHA" "$OUT_23_10_rw"
check "23-US10: email-cli list-accounts lists beta" \
    "$BETA" "$OUT_23_10_rw"

fi

if phase_wanted 24; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 24 — --label alias and label name resolution
#
# User Stories:
#   US-01  --label is accepted as alias for --folder (IMAP mode)
#   US-02  email-cli-ro accepts --label alias (IMAP mode)
#   US-03  --label with unknown name falls back to using value as-is
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 24: --label alias ---"

# ── US-01: --label works as alias for --folder (IMAP) ─────────────────────
OUT_24_01_folder=$(run_list "$H_ALPHA" "" INBOX)
OUT_24_01_label=$(
    export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" list --batch --label INBOX 2>&1 || true)
check "24-US01: --label INBOX returns same as --folder INBOX" \
    "AlphaAccountMsg" "$OUT_24_01_label"

# ── US-02: email-cli-ro accepts --label alias ─────────────────────────────
OUT_24_02=$(
    export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" list --batch --label INBOX 2>&1 || true)
check "24-US02: email-cli-ro --label INBOX works" \
    "AlphaAccountMsg" "$OUT_24_02"

# ── US-03: --label with a name not in cache falls back gracefully ──────────
# (IMAP: an unknown label/folder returns empty or error, not a crash)
OUT_24_03=$(
    export HOME="$H_ALPHA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" list --batch --label "NonExistentFolder" 2>&1 || true)
# Should not crash — either empty list or server error message
check_not "24-US03: unknown label does not crash (no segfault output)" \
    "Segmentation fault" "$OUT_24_03"

fi

if phase_wanted 25; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 25 — IMAP with 2 accounts (200 + 250 messages) + cross-contamination
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 25: IMAP with 2 accounts (200 + 250 messages) ---"

alloc_port IMAP200_PORT
alloc_port IMAP250_PORT
IMAP200_LOG="$PROJECT_ROOT/build/tests/functional/work-$$/mock_server200.log"
IMAP250_LOG="$PROJECT_ROOT/build/tests/functional/work-$$/mock_server250.log"
echo "Starting mock IMAP server A (port $IMAP200_PORT, 200 messages)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$IMAP200_PORT MOCK_IMAP_COUNT=200 \
    MOCK_IMAP_MSG_PREFIX="IMapA-Message" \
    "$MOCK_SERVER_BIN") >"$IMAP200_LOG" 2>&1 &
SERVER200_PID=$!
echo "Starting mock IMAP server B (port $IMAP250_PORT, 250 messages)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$IMAP250_PORT MOCK_IMAP_COUNT=250 \
    MOCK_IMAP_MSG_PREFIX="IMapB-Message" \
    "$MOCK_SERVER_BIN") >"$IMAP250_LOG" 2>&1 &
SERVER250_PID=$!
sleep 0.5

H_200="./build/tests/functional/work-$$/homes/200-$$"
ACCT200="imap200@test.local"
ACCT250="imap250@test.local"
rm -rf "./build/tests/functional/work-$$/homes/200-$$"
mkdir -p "$H_200/.config/email-cli/accounts/$ACCT200"
mkdir -p "$H_200/.config/email-cli/accounts/$ACCT250"
cat > "$H_200/.config/email-cli/accounts/$ACCT200/config.ini" <<CFG200
EMAIL_HOST=imaps://localhost:$IMAP200_PORT
EMAIL_USER=$ACCT200
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
EMAIL_SENT_FOLDER=INBOX.Sent
SSL_NO_VERIFY=1
CFG200
cat > "$H_200/.config/email-cli/accounts/$ACCT250/config.ini" <<CFG250
EMAIL_HOST=imaps://localhost:$IMAP250_PORT
EMAIL_USER=$ACCT250
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
EMAIL_SENT_FOLDER=INBOX.Sent
SSL_NO_VERIFY=1
CFG250

run_200() {
    (export HOME="$H_200"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     "$BIN_DIR/email-cli" "$ACCT200" "$@" 2>&1 || true)
}

run_250() {
    (export HOME="$H_200"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     "$BIN_DIR/email-cli" "$ACCT250" "$@" 2>&1 || true)
}

# ── IMAP-A (200 messages, prefix "IMapA-Message") ────────────────────────
# 25.1 list --all --limit 200
L200=$(run_200 --batch list --all --limit 200)
check "25.1 imap-A list: count line shows 200" "200" "$L200"

# 25.2 list with limit + offset
L200_off=$(run_200 --batch list --all --limit 10 --offset 1)
check "25.2 imap-A list --offset 1 --limit 10: shows messages" "IMapA" "$L200_off"

# 25.3 list with higher offset
L200_off2=$(run_200 --batch list --all --limit 10 --offset 101)
check "25.3 imap-A list --offset 101 --limit 10: shows messages" "IMapA" "$L200_off2"

# 25.4 show specific UIDs
S200_1=$(run_200 show 1)
check "25.4 imap-A show UID 1: subject shown" "IMapA-Message 1" "$S200_1"

S200_50=$(run_200 show 50)
check "25.5 imap-A show UID 50: subject shown" "IMapA-Message 50" "$S200_50"

S200_100=$(run_200 show 100)
check "25.6 imap-A show UID 100: subject shown" "IMapA-Message 100" "$S200_100"

# 25.7 Verify different UIDs show different subjects
check_not "25.7 imap-A show UID 50: not UID 1 subject" "IMapA-Message 1$" "$S200_50"
check_not "25.8 imap-A show UID 100: not UID 50 subject" "IMapA-Message 50$" "$S200_100"

# 25.9 list-attachments for UID with attachment (multiples of 10)
LA200=$(run_200 --batch list-attachments 10)
check "25.9 imap-A list-attachments UID 10: notes_10.txt listed" "notes_10" "$LA200"

# 25.10 list-attachments for UID without attachment
LA200_1=$(run_200 --batch list-attachments 1)
check_not "25.10 imap-A list-attachments UID 1: no notes_10.txt" "notes_10" "$LA200_1"

# 25.11 save-attachment
SAVE200_DIR="./build/tests/functional/work-$$/homes/attach200-$$"
mkdir -p "$SAVE200_DIR"
SA200=$(run_200 --batch save-attachment 10 notes_10.txt "$SAVE200_DIR")
check "25.11 imap-A save-attachment UID 10: confirmation" "aved\|uccessful\|notes" "$SA200"
check "25.12 imap-A save-attachment UID 10: file exists" "^ok$" \
    "$(test -f "$SAVE200_DIR/notes_10.txt" && echo ok || echo missing)"
rm -rf "./build/tests/functional/work-$$/homes/attach200-$$"

# 25.13 list-folders
F200=$(run_200 list-folders)
check "25.13 imap-A list-folders: INBOX listed" "INBOX" "$F200"

# ── IMAP-B (250 messages, prefix "IMapB-Message") ────────────────────────
# 25.14 list all 250 messages
L250=$(run_250 --batch list --all --limit 250)
check "25.14 imap-B list: count line shows 250" "250" "$L250"

# 25.15 list offset
L250_off=$(run_250 --batch list --all --limit 10 --offset 201)
check "25.15 imap-B list --offset 201 --limit 10: shows messages" "IMapB" "$L250_off"

# 25.16 show UID 1
S250_1=$(run_250 show 1)
check "25.16 imap-B show UID 1: correct subject" "IMapB-Message 1" "$S250_1"

# 25.17 show UID 200
S250_200=$(run_250 show 200)
check "25.17 imap-B show UID 200: correct subject" "IMapB-Message 200" "$S250_200"

# 25.18 show UID 250
S250_250=$(run_250 show 250)
check "25.18 imap-B show UID 250: correct subject" "IMapB-Message 250" "$S250_250"

# 25.19 list-attachments UID 20 (multiple of 10)
LA250=$(run_250 --batch list-attachments 20)
check "25.19 imap-B list-attachments UID 20: notes_20.txt listed" "notes_20" "$LA250"

# 25.20 save-attachment
SAVE250_DIR="./build/tests/functional/work-$$/homes/attach250-$$"
mkdir -p "$SAVE250_DIR"
SA250=$(run_250 --batch save-attachment 20 notes_20.txt "$SAVE250_DIR")
check "25.20 imap-B save-attachment UID 20: confirmation" "aved\|uccessful\|notes" "$SA250"
check "25.21 imap-B save-attachment UID 20: file exists" "^ok$" \
    "$(test -f "$SAVE250_DIR/notes_20.txt" && echo ok || echo missing)"
rm -rf "./build/tests/functional/work-$$/homes/attach250-$$"

# ── IMAP cross-contamination checks ──────────────────────────────────────
# 25.22 IMAP-A list must NOT contain IMAP-B subjects
check_not "25.22 imap-A list: no IMapB subjects" "IMapB" "$L200"

# 25.23 IMAP-B list must NOT contain IMAP-A subjects
check_not "25.23 imap-B list: no IMapA subjects" "IMapA" "$L250"

# 25.24 IMAP-A show must NOT contain IMAP-B subject text
check_not "25.24 imap-A show UID 1: no IMapB content" "IMapB" "$S200_1"

# 25.25 IMAP-B has 250 messages; IMAP-A must report 200 max
check_not "25.25 imap-A list: count not 250" "250 message" "$L200"

fi

if phase_wanted 26; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 26 — Gmail sync + offline list (2 accounts + cross-contamination)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 26: Gmail sync + offline list (2 accounts) ---"

alloc_port GMAIL_PORT_A
alloc_port GMAIL_PORT_B
GMAIL_LOG_A="$PROJECT_ROOT/build/tests/functional/work-$$/mock_gmail_a.log"
GMAIL_LOG_B="$PROJECT_ROOT/build/tests/functional/work-$$/mock_gmail_b.log"
echo "Starting mock Gmail API server A (port $GMAIL_PORT_A, 200 messages)..."
(MOCK_GMAIL_PORT=$GMAIL_PORT_A MOCK_GMAIL_COUNT=200 \
    MOCK_GMAIL_EMAIL="test@gmail.com" \
    "$MOCK_GMAIL_BIN") >"$GMAIL_LOG_A" 2>&1 &
GMAIL_SERVER_A_PID=$!
echo "Starting mock Gmail API server B (port $GMAIL_PORT_B, 150 messages)..."
(MOCK_GMAIL_PORT=$GMAIL_PORT_B MOCK_GMAIL_COUNT=150 \
    MOCK_GMAIL_EMAIL="test2@gmail.com" \
    MOCK_GMAIL_SUBJECT_PREFIX="GmailB-" \
    "$MOCK_GMAIL_BIN") >"$GMAIL_LOG_B" 2>&1 &
GMAIL_SERVER_B_PID=$!
sleep 0.5

# Shared temp home for both Gmail accounts (tests account isolation within one HOME)
H_GMAIL="./build/tests/functional/work-$$/homes/gmail-$$"
GMAIL_ACCT_A="test@gmail.com"
GMAIL_ACCT_B="test2@gmail.com"
rm -rf "./build/tests/functional/work-$$/homes/gmail-$$"
mkdir -p "$H_GMAIL/config/email-cli/accounts/$GMAIL_ACCT_A"
mkdir -p "$H_GMAIL/config/email-cli/accounts/$GMAIL_ACCT_B"
mkdir -p "$H_GMAIL/data"
cat > "$H_GMAIL/config/email-cli/accounts/$GMAIL_ACCT_A/config.ini" <<GCFG_A
EMAIL_HOST=
EMAIL_USER=$GMAIL_ACCT_A
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=fakefaketoken
GCFG_A
cat > "$H_GMAIL/config/email-cli/accounts/$GMAIL_ACCT_B/config.ini" <<GCFG_B
EMAIL_HOST=
EMAIL_USER=$GMAIL_ACCT_B
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=fakefaketoken2
GCFG_B

# Helper: sync account A
run_gmail_sync_a() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     export GMAIL_TEST_TOKEN=testtoken
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_A/gmail/v1/users/me"
     "$BIN_DIR/email-sync" --account "$GMAIL_ACCT_A" 2>&1 || true)
}

# Helper: sync account B
run_gmail_sync_b() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     export GMAIL_TEST_TOKEN=testtoken2
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_B/gmail/v1/users/me"
     "$BIN_DIR/email-sync" --account "$GMAIL_ACCT_B" 2>&1 || true)
}

# Helper: read-only commands for account A
run_gmail_ro_a() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     export GMAIL_TEST_TOKEN=testtoken
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_A/gmail/v1/users/me"
     "$BIN_DIR/email-cli-ro" "$GMAIL_ACCT_A" "$@" 2>&1 || true)
}

# Helper: read-only commands for account B
run_gmail_ro_b() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     export GMAIL_TEST_TOKEN=testtoken2
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_B/gmail/v1/users/me"
     "$BIN_DIR/email-cli-ro" "$GMAIL_ACCT_B" "$@" 2>&1 || true)
}

# ── Gmail account A (test@gmail.com, 200 messages) ────────────────────────
# 26.1 Run email-sync for account A
SYNC26A=$(run_gmail_sync_a)
check "26.1 gmail-A sync: fetched messages" "fetched\|stored\|already\|downloaded\|cached" "$SYNC26A"

# 26.2 list --all --limit 200
GL_A=$(run_gmail_ro_a --batch list --all --limit 200)
check "26.2 gmail-A list: count shows messages" "message" "$GL_A"
check "26.3 gmail-A list: Message 1 present" "Message 1" "$GL_A"
check "26.4 gmail-A list: Message 200 present" "Message 200" "$GL_A"

# 26.5 show message 1
GS_A1=$(run_gmail_ro_a show 0000000000000001)
check "26.5 gmail-A show 1: subject present" "Message 1" "$GS_A1"
check "26.6 gmail-A show 1: sender present" "Sender 1" "$GS_A1"

# 26.7 show message 10 (has attachment)
GS_A10=$(run_gmail_ro_a show 000000000000000a)
check "26.7 gmail-A show 10: subject present" "Message 10" "$GS_A10"

# 26.8 list-attachments for message 10
GLA_A=$(run_gmail_ro_a --batch list-attachments 000000000000000a)
check "26.8 gmail-A list-attachments 10: notes_10.txt listed" "notes_10" "$GLA_A"

# 26.9 save-attachment for message 10
GSAVE_A_DIR="./build/tests/functional/work-$$/homes/gattach-a-$$"
mkdir -p "$GSAVE_A_DIR"
GSA_A=$(run_gmail_ro_a --batch save-attachment 000000000000000a notes_10.txt "$GSAVE_A_DIR")
check "26.9 gmail-A save-attachment: exit ok" "aved\|uccessful\|notes\|ok" "$GSA_A"
check "26.10 gmail-A save-attachment: file exists" "^ok$" \
    "$(test -f "$GSAVE_A_DIR/notes_10.txt" && echo ok || echo missing)"
rm -rf "./build/tests/functional/work-$$/homes/gattach-a-$$"

# 26.11 list-labels account A
GF_A=$(run_gmail_ro_a --batch list-labels)
check "26.11 gmail-A list-labels: INBOX listed" "INBOX" "$GF_A"
check "26.12 gmail-A list-labels: Work listed" "Work" "$GF_A"

# ── Gmail account B (test2@gmail.com, 150 messages, prefix GmailB-) ───────
# 26.13 Sync account B
SYNC26B=$(run_gmail_sync_b)
check "26.13 gmail-B sync: fetched messages" "fetched\|stored\|already\|downloaded\|cached" "$SYNC26B"

# 26.14 list all 150 messages
GL_B=$(run_gmail_ro_b --batch list --all --limit 150)
check "26.14 gmail-B list: count shows messages" "message" "$GL_B"
check "26.15 gmail-B list: GmailB-Message 1 present" "GmailB-Message 1" "$GL_B"
check "26.16 gmail-B list: GmailB-Message 150 present" "GmailB-Message 150" "$GL_B"

# 26.17 show message 1 from account B
GS_B1=$(run_gmail_ro_b show 0000000000000001)
check "26.17 gmail-B show 1: subject has prefix" "GmailB-Message 1" "$GS_B1"
check "26.18 gmail-B show 1: sender present" "Sender 1" "$GS_B1"

# 26.19 show message 20 (has attachment, 20 % 10 == 0)
GS_B20=$(run_gmail_ro_b show 0000000000000014)
check "26.19 gmail-B show 20: correct subject" "GmailB-Message 20" "$GS_B20"

# 26.20 list-attachments for message 20
GLA_B=$(run_gmail_ro_b --batch list-attachments 0000000000000014)
check "26.20 gmail-B list-attachments 20: GmailB-notes_20.txt listed" "GmailB-notes_20" "$GLA_B"

# 26.21 save-attachment for message 20 (account B)
GSAVE_B_DIR="./build/tests/functional/work-$$/homes/gattach-b-$$"
mkdir -p "$GSAVE_B_DIR"
GSA_B=$(run_gmail_ro_b --batch save-attachment 0000000000000014 GmailB-notes_20.txt "$GSAVE_B_DIR")
check "26.21 gmail-B save-attachment: exit ok" "aved\|uccessful\|notes\|ok" "$GSA_B"
check "26.22 gmail-B save-attachment: file exists" "^ok$" \
