if phase_wanted 27; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 27 — Gmail label index rebuild (--rebuild-index + auto-rebuild)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 27: Gmail label index rebuild ---"

LABELS_DIR_A="$H_GMAIL/data/email-cli/accounts/$GMAIL_ACCT_A/labels"
LABELS_DIR_B="$H_GMAIL/data/email-cli/accounts/$GMAIL_ACCT_B/labels"
INBOX_IDX_A="$LABELS_DIR_A/INBOX.idx"
INBOX_IDX_B="$LABELS_DIR_B/INBOX.idx"

# Helper: run email-sync --rebuild-index (offline, no API URL needed)
run_rebuild_idx() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     "$BIN_DIR/email-sync" "$@" 2>&1 || true)
}

# 27.1 After Phase 26 sync, INBOX.idx should exist for account A
check "27.1 gmail-A INBOX.idx exists after sync" "^ok$" \
    "$([ -f "$INBOX_IDX_A" ] && echo ok || echo missing)"

# Record entry count before deletion
IDX_A_BEFORE=$(wc -c < "$INBOX_IDX_A" 2>/dev/null || echo "0")

# 27.2 Delete all .idx files for account A
rm -f "$LABELS_DIR_A"/*.idx
check "27.2 gmail-A idx files deleted" "^ok$" \
    "$([ ! -f "$INBOX_IDX_A" ] && echo ok || echo still-present)"

# 27.3 Run --rebuild-index for account A only (offline, no server contact)
REBUILD27A=$(run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A")
check "27.3 rebuild-index --account A: exits cleanly" "^ok$" \
    "$([ $? -eq 0 ] && echo ok || echo nonzero)"

# 27.4 INBOX.idx recreated for account A
check "27.4 gmail-A INBOX.idx recreated by --rebuild-index" "^ok$" \
    "$([ -f "$INBOX_IDX_A" ] && echo ok || echo missing)"

# 27.5 Entry count unchanged after rebuild
IDX_A_AFTER=$(wc -c < "$INBOX_IDX_A" 2>/dev/null || echo "0")
check "27.5 gmail-A INBOX.idx size unchanged after rebuild" "^ok$" \
    "$([ "$IDX_A_AFTER" = "$IDX_A_BEFORE" ] && echo ok || echo "changed-${IDX_A_BEFORE}-to-${IDX_A_AFTER}")"

# 27.6 Run --rebuild-index for ALL accounts (no --account flag)
rm -f "$LABELS_DIR_A"/*.idx "$LABELS_DIR_B"/*.idx
REBUILD27ALL=$(run_rebuild_idx --rebuild-index)
check "27.6 rebuild-index (all accounts): exits cleanly" "^ok$" \
    "$([ $? -eq 0 ] && echo ok || echo nonzero)"

# 27.7 Account A INBOX.idx recreated
check "27.7 gmail-A INBOX.idx recreated by all-accounts rebuild" "^ok$" \
    "$([ -f "$INBOX_IDX_A" ] && echo ok || echo missing)"

# 27.8 Account B INBOX.idx recreated
check "27.8 gmail-B INBOX.idx recreated by all-accounts rebuild" "^ok$" \
    "$([ -f "$INBOX_IDX_B" ] && echo ok || echo missing)"

# 27.9 Auto-rebuild during full sync:
#   Delete historyId (forces full sync) + .idx files, then run sync.
#   Full sync should rebuild indexes even when all messages are already cached.
HIST_A="$H_GMAIL/data/email-cli/accounts/$GMAIL_ACCT_A/gmail_history_id"
rm -f "$HIST_A" "$LABELS_DIR_A"/*.idx
SYNC27A=$(run_gmail_sync_a)
check "27.9 auto-rebuild: full sync runs after historyId deleted" \
    "fetched\|cached\|stored\|downloaded\|queued\|server" "$SYNC27A"

# 27.10 After auto-rebuild full sync, INBOX.idx exists for account A
check "27.10 gmail-A INBOX.idx recreated by auto-rebuild full sync" "^ok$" \
    "$([ -f "$INBOX_IDX_A" ] && echo ok || echo missing)"

# 27.11 After rebuild, list shows messages — confirms index is functional, not just present
GL27=$(run_gmail_ro_a --batch list --all --limit 200)
check "27.11 gmail-A list: messages accessible after rebuild (index functional)" "Message 1" "$GL27"

fi

if phase_wanted 28; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 28 — Hex UID acceptance (US-6: Gmail `list` outputs hex UIDs)
# Verifies that all commands that accept a UID accept the 16-char hex format
# returned by `list`, not just the decimal format used by IMAP.
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 28: hex UID acceptance ---"

# email-cli (writable commands) with Gmail account A environment
run_gmail_cli_a() {
    (export XDG_CONFIG_HOME="$H_GMAIL/config"
     export XDG_DATA_HOME="$H_GMAIL/data"
     export XDG_CACHE_HOME="$H_GMAIL/cache"
     export HOME="$H_GMAIL"
     export GMAIL_TEST_TOKEN=testtoken
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_A/gmail/v1/users/me"
     "$BIN_DIR/email-cli" "$GMAIL_ACCT_A" --batch "$@" 2>&1 || true)
}

HEX_UID="0000000000000001"   # message 1, synced in Phase 26+27

# 28.1 mark-read: hex UID must not produce a parse error
MR28=$(run_gmail_cli_a mark-read "$HEX_UID"; echo "exit-code=$?")
check "exit status of MR28 is 0" "exit-code=0" "$MR28"
check_not "28.1 mark-read hex UID: no parse error"  "invalid UID\|positive integer" "$MR28"

# 28.2 mark-unread: hex UID must not produce a parse error
MU28=$(run_gmail_cli_a mark-unread "$HEX_UID"; echo "exit-code=$?")
check "exit status of MU28 is 0" "exit-code=0" "$MU28"
check_not "28.2 mark-unread hex UID: no parse error"  "invalid UID\|positive integer" "$MU28"

# 28.3 mark-starred: hex UID must not produce a parse error
MS28=$(run_gmail_cli_a mark-starred "$HEX_UID"; echo "exit-code=$?")
check "exit status of MS28 is 0" "exit-code=0" "$MS28"
check_not "28.3 mark-starred hex UID: no parse error"  "invalid UID\|positive integer" "$MS28"

# 28.4 remove-starred: hex UID must not produce a parse error
RS28=$(run_gmail_cli_a remove-starred "$HEX_UID"; echo "exit-code=$?")
check "exit status of RS28 is 0" "exit-code=0" "$RS28"
check_not "28.4 remove-starred hex UID: no parse error"  "invalid UID\|positive integer" "$RS28"

# 28.5 add-label: hex UID must not produce a parse error
AL28=$(run_gmail_cli_a add-label "$HEX_UID" INBOX; echo "exit-code=$?")
check "exit status of AL28 is 0" "exit-code=0" "$AL28"
check_not "28.5 add-label hex UID: no parse error"  "invalid UID\|positive integer" "$AL28"

# 28.6 remove-label: hex UID must not produce a parse error
RL28=$(run_gmail_cli_a remove-label "$HEX_UID" INBOX; echo "exit-code=$?")
check "exit status of RL28 is 0" "exit-code=0" "$RL28"
check_not "28.6 remove-label hex UID: no parse error"  "invalid UID\|positive integer" "$RL28"

# 28.7 show (email-cli-ro): hex UID must not produce a parse error
SH28=$(run_gmail_ro_a show "$HEX_UID")
check_not "28.7 show hex UID: no parse error"  "invalid UID\|positive integer" "$SH28"

# 28.8 list-attachments (email-cli-ro): hex UID must not produce a parse error
LA28=$(run_gmail_ro_a --batch list-attachments "$HEX_UID")
check_not "28.8 list-attachments hex UID: no parse error"  "invalid UID\|positive integer" "$LA28"

# 28.9 save-attachment: hex UID must not produce a parse error
#   (filename arg keeps command from showing usage; any other error is acceptable)
SA28=$(run_gmail_ro_a save-attachment "$HEX_UID" nosuchfile.txt "$WORK_DIR")
check_not "28.9 save-attachment hex UID: no parse error"  "invalid UID\|positive integer" "$SA28"

# 28.10 Truly invalid UID (garbage string) is still rejected
BAD28=$(run_gmail_cli_a mark-read "notavaliduid123x")
check "28.10 mark-read garbage UID rejected"  "invalid UID\|Error" "$BAD28"

# 28.11 Regression: IMAP decimal UID still accepted (main.c)
H28_IMAP="./build/tests/functional/work-$$/homes/hex28-$$"
make_home "$H28_IMAP" "alpha@test.local" $IMAP1_PORT
DEC28=$( (export HOME="$H28_IMAP"
    unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" --batch mark-read 42 2>&1 ; echo "exit-code=$?") )
check "exit status of DEC28 is 0" "exit-code=0" "$DEC28"
check_not "28.11 mark-read decimal UID (IMAP): no parse error"  "invalid UID\|positive integer" "$DEC28"
rm -rf "./build/tests/functional/work-$$/homes/hex28-$$"

fi

if phase_wanted 29; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 29 — .hdr labels CSV / flags-int consistency after local mutations
#
# Regression guard for the bug where label-mutating operations updated .idx
# but not .hdr labels CSV, so rebuild_label_indexes (run on every full sync)
# silently undid the changes.  Each test follows the pattern:
#   1. mutate via CLI or key emulation
#   2. run --rebuild-index (simulates the full-sync rebuild step)
#   3. verify the .idx reflects the mutation (not the pre-mutation state)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 29: .hdr labels CSV / flags-int consistency ---"

# Helpers reused from Phase 27/28
# run_gmail_cli_a, run_rebuild_idx, LABELS_DIR_A, HEX_UID already defined

idx_contains() { grep -qF "$1" "$2" 2>/dev/null && echo yes || echo no; }

# 29.1 mark-read: UID removed from UNREAD.idx AND stays removed after rebuild
MR29=$(run_gmail_cli_a mark-read "$HEX_UID"; echo "exit-code=$?")
check "exit status of MR29 is 0" "exit-code=0" "$MR29"
check_not "29.1a mark-read: no error"  "Error\|invalid UID" "$MR29"
check "29.1b mark-read: UID removed from UNREAD.idx immediately" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.1c mark-read: UID still absent from UNREAD.idx after rebuild" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# 29.2 mark-unread: UID re-added to UNREAD.idx AND persists after rebuild
MU29=$(run_gmail_cli_a mark-unread "$HEX_UID"; echo "exit-code=$?")
check "exit status of MU29 is 0" "exit-code=0" "$MU29"
check_not "29.2a mark-unread: no error"  "Error\|invalid UID" "$MU29"
check "29.2b mark-unread: UID back in UNREAD.idx immediately" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.2c mark-unread: UID still in UNREAD.idx after rebuild" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# 29.3 mark-starred: UID added to STARRED.idx AND persists after rebuild
MS29=$(run_gmail_cli_a mark-starred "$HEX_UID"; echo "exit-code=$?")
check "exit status of MS29 is 0" "exit-code=0" "$MS29"
check_not "29.3a mark-starred: no error"  "Error\|invalid UID" "$MS29"
check "29.3b mark-starred: UID in STARRED.idx immediately" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.3c mark-starred: UID still in STARRED.idx after rebuild" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"

# 29.4 remove-starred: UID removed from STARRED.idx AND stays removed after rebuild
RS29=$(run_gmail_cli_a remove-starred "$HEX_UID"; echo "exit-code=$?")
check "exit status of RS29 is 0" "exit-code=0" "$RS29"
check_not "29.4a remove-starred: no error"  "Error\|invalid UID" "$RS29"
check "29.4b remove-starred: UID absent from STARRED.idx immediately" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.4c remove-starred: UID still absent from STARRED.idx after rebuild" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"

# 29.5 add-label UNREAD via CLI: persists after rebuild
AL29=$(run_gmail_cli_a add-label "$HEX_UID" UNREAD 2>&1 || true)
check "29.5b add-label UNREAD: UID in UNREAD.idx immediately" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.5c add-label UNREAD: UID still in UNREAD.idx after rebuild" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# 29.6 remove-label UNREAD via CLI: persists after rebuild
RL29=$(run_gmail_cli_a remove-label "$HEX_UID" UNREAD 2>&1 || true)
check "29.6b remove-label UNREAD: UID absent from UNREAD.idx immediately" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
run_rebuild_idx --rebuild-index --account "$GMAIL_ACCT_A" >/dev/null 2>&1
check "29.6c remove-label UNREAD: UID still absent after rebuild" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# ── Full email-sync regression tests ─────────────────────────────────────
# The original reported bug: mark-read then email-sync → message appears
# unread again.  This exercises the full sync path (rebuild_label_indexes
# called from gmail_sync_full) rather than just --rebuild-index.
# Force a full sync by deleting the historyId before each run.

HIST_A="$H_GMAIL/data/email-cli/accounts/$GMAIL_ACCT_A/gmail_history_id"

# 29.7 mark-read survives full email-sync (the original reported bug)
run_gmail_cli_a mark-read "$HEX_UID" >/dev/null 2>&1
check "29.7a mark-read: UID absent from UNREAD.idx before sync" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
rm -f "$HIST_A"
run_gmail_sync_a >/dev/null 2>&1
check "29.7b mark-read: UID still absent from UNREAD.idx after full sync" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# 29.8 mark-unread survives full email-sync
run_gmail_cli_a mark-unread "$HEX_UID" >/dev/null 2>&1
check "29.8a mark-unread: UID in UNREAD.idx before sync" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"
rm -f "$HIST_A"
run_gmail_sync_a >/dev/null 2>&1
check "29.8b mark-unread: UID still in UNREAD.idx after full sync" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/UNREAD.idx")"

# 29.9 mark-starred survives full email-sync
run_gmail_cli_a mark-starred "$HEX_UID" >/dev/null 2>&1
check "29.9a mark-starred: UID in STARRED.idx before sync" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"
rm -f "$HIST_A"
run_gmail_sync_a >/dev/null 2>&1
check "29.9b mark-starred: UID still in STARRED.idx after full sync" "yes" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"

# 29.10 remove-starred survives full email-sync
run_gmail_cli_a remove-starred "$HEX_UID" >/dev/null 2>&1
check "29.10a remove-starred: UID absent from STARRED.idx before sync" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"
rm -f "$HIST_A"
run_gmail_sync_a >/dev/null 2>&1
check "29.10b remove-starred: UID still absent from STARRED.idx after full sync" "no" \
    "$(idx_contains "$HEX_UID" "$LABELS_DIR_A/STARRED.idx")"

fi

if phase_wanted 30; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 30 — Gmail smart sync: reconcile + pending_fetch + incremental fast path
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 30: Gmail smart sync (reconcile/pending_fetch/incremental) ---"

# Use a fresh home dir so Phase 26-29 state does not interfere
H_GSYNC="./build/tests/functional/work-$$/homes/gsync-$$"
GSYNC_ACCT="gsync@gmail.com"
rm -rf "./build/tests/functional/work-$$/homes/gsync-$$"
mkdir -p "$H_GSYNC/config/email-cli/accounts/$GSYNC_ACCT"
mkdir -p "$H_GSYNC/data"
cat > "$H_GSYNC/config/email-cli/accounts/$GSYNC_ACCT/config.ini" <<GSYNC_CFG
EMAIL_HOST=
EMAIL_USER=$GSYNC_ACCT
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=faketoken30
GSYNC_CFG

GSYNC_DATA_DIR="$H_GSYNC/data/email-cli/accounts/$GSYNC_ACCT"
GSYNC_PENDING="$GSYNC_DATA_DIR/pending_fetch.tsv"
GSYNC_HISTID="$GSYNC_DATA_DIR/gmail_history_id"

run_gsync() {
    (export XDG_CONFIG_HOME="$H_GSYNC/config"
     export XDG_DATA_HOME="$H_GSYNC/data"
     export XDG_CACHE_HOME="$H_GSYNC/cache"
     export HOME="$H_GSYNC"
     export GMAIL_TEST_TOKEN=testtoken30
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_A/gmail/v1/users/me"
     "$BIN_DIR/email-sync" --account "$GSYNC_ACCT" 2>&1 || true)
}

run_gsync_ro() {
    (export XDG_CONFIG_HOME="$H_GSYNC/config"
     export XDG_DATA_HOME="$H_GSYNC/data"
     export XDG_CACHE_HOME="$H_GSYNC/cache"
     export HOME="$H_GSYNC"
     export GMAIL_TEST_TOKEN=testtoken30
     export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_A/gmail/v1/users/me"
     "$BIN_DIR/email-cli-ro" "$GSYNC_ACCT" "$@" 2>&1 || true)
}

# 30.1 First sync: no historyId → reconcile + fetch_pending
SYNC30A=$(run_gsync)
check "30.1 first sync: downloads messages (fetched/already)" \
    "fetched\|already\|downloaded" "$SYNC30A"

# 30.2 After first sync: pending_fetch.tsv must be empty (all messages downloaded)
PF_COUNT30=$(wc -l < "$GSYNC_PENDING" 2>/dev/null || echo 0)
check "30.2 first sync: pending_fetch.tsv empty after sync" "0" "$PF_COUNT30"

# 30.3 After first sync: historyId must be saved
check "30.3 first sync: historyId saved" "^ok$" \
    "$(test -f "$GSYNC_HISTID" && echo ok || echo missing)"

# 30.4 After first sync: messages are accessible
GL30=$(run_gsync_ro --batch list --all --limit 200)
check "30.4 first sync: messages accessible" "Message 1" "$GL30"

# 30.5 Second sync: historyId present, no pending → fast incremental path
# Mock server always returns an empty history response, so incremental
# succeeds with 0 changes (the server has no history endpoint that signals
# expiry for these tests).
SYNC30B=$(run_gsync)
check "30.5 second sync: runs without error" "^ok$" "$(echo "$SYNC30B" | head -1; echo ok)"
# No reconcile message should appear (fast incremental path)
check_not "30.5b second sync: no 'Listing messages' output (incremental)" \
    "Listing messages" "$SYNC30B"

# 30.6 Simulate interrupted sync: manually populate pending_fetch.tsv
# Delete a cached message and add its UID to pending_fetch.tsv
RESUME_UID="0000000000000002"
rm -f "$GSYNC_DATA_DIR/messages/00/00/0000000000000002.eml" 2>/dev/null || true
find "$GSYNC_DATA_DIR/messages" -name "0000000000000002.eml" -delete 2>/dev/null || true
echo "$RESUME_UID" > "$GSYNC_PENDING"
PF_BEFORE=$(wc -l < "$GSYNC_PENDING")
check "30.6 interrupted sync: pending_fetch.tsv has 1 entry before resume" "1" "$PF_BEFORE"

# 30.7 Run sync with pending entry: should drain pending then go incremental
# (not reconcile — historyId is valid so fast path is taken after drain)
SYNC30C=$(run_gsync)
check "30.7 resume sync: completes without error" "^ok$" "$(echo ok)"
# After resume, pending_fetch.tsv must be empty again
PF_AFTER=$(wc -l < "$GSYNC_PENDING" 2>/dev/null || echo 0)
check "30.8 resume sync: pending_fetch.tsv empty after resume" "0" "$PF_AFTER"
# Must NOT have run a full reconcile — incremental fast path after draining pending
check_not "30.8b resume sync: no reconcile (incremental after drain)" \
    "Listing messages" "$SYNC30C"

# 30.9 Force reconcile by removing historyId: should re-list server
rm -f "$GSYNC_HISTID"
SYNC30D=$(run_gsync)
check "30.9 forced reconcile (no historyId): lists server" \
    "messages on server\|Listing\|fetched\|already\|downloaded" "$SYNC30D"

# Cleanup Phase 30
rm -rf "./build/tests/functional/work-$$/homes/gsync-$$"

# Cleanup Phase 26+27+28+29
kill "$GMAIL_SERVER_A_PID" "$GMAIL_SERVER_B_PID" 2>/dev/null || true
rm -rf "./build/tests/functional/work-$$/homes/gmail-$$"

fi

if phase_wanted 31; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 31 — URL word-wrap: long URLs must not be hard-broken mid-token
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 31: URL word-wrap (plain-text, no hard line breaks) ---"

LONG_URL="https://www.agroinform.hu/aprohirdetes_adatlap/gep/gyumolcstermesztes-gepei/perfect-rf-egyoldalas-lengotarcsas-kasza-gyumolcs-es-szoloultetvenyekhez/h_7206309?ref=0a20571a"

alloc_port URL_PORT
H_URL="./build/tests/functional/work-$$/homes/urlwrap"
URL_LOG="$PROJECT_ROOT/build/tests/functional/work-$$/mock_urlwrap.log"
make_home "$H_URL" "urlwrap@test.local" "$URL_PORT"

(cd "$PROJECT_ROOT/build" && \
    MOCK_IMAP_PORT=$URL_PORT \
    MOCK_IMAP_LONG_URL="$LONG_URL" \
    "$MOCK_SERVER_BIN") >"$URL_LOG" 2>&1 &
URL_SERVER_PID=$!
sleep 0.3

URL_OUT=$(run_show "$H_URL" "")

check     "31.1 long URL: hostname present"    "agroinform.hu"   "$URL_OUT"
check     "31.2 long URL: query param present" "ref=0a20571a"    "$URL_OUT"
# Chars 71-91 of the URL straddle the col-80 boundary ("gepei/perfect-rf-egyo").
# With a hard break the sequence is split by \n; without a hard break it is intact.
# (Start at 71, not 70, to avoid a leading '-' that grep would interpret as option.)
URL_STRADDLE=$(printf '%s' "$LONG_URL" | cut -c71-91)
check     "31.3 URL not broken at col 80"      "$URL_STRADDLE"   "$URL_OUT"

# Cleanup Phase 31
kill "$URL_SERVER_PID" 2>/dev/null || true
rm -rf "./build/tests/functional/work-$$/homes/urlwrap"

fi

if phase_wanted 32; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 32 — Gmail incremental sync: historyId from list, new messages, expired
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 32: Gmail incremental sync (historyId / new msgs / expired) ---"

GMAIL_INC_LOG="$PROJECT_ROOT/build/tests/functional/work-$$"

# ── Phase 32a: historyId captured from messages.list (not /profile) ──────
