run_ginc_a_sync() {
    (export XDG_CONFIG_HOME="$H_GINC_A/config"
     export XDG_DATA_HOME="$H_GINC_A/data"
     export XDG_CACHE_HOME="$H_GINC_A/cache"
     export HOME="$H_GINC_A"
     export GMAIL_TEST_TOKEN=testtoken32a
