     "$BIN_DIR/email-sync" --account "$GINC_ACCT_C" 2>&1 || true)
}

# Start normal mock, do first sync to get a saved historyId
(cd "$PROJECT_ROOT/build" && \
    MOCK_GMAIL_PORT=$GINC_PORT_C \
    MOCK_GMAIL_COUNT=3 \
    MOCK_GMAIL_HISTID=9000 \
