fi

if phase_wanted 33; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 33 — IMAP CONDSTORE incremental sync (RFC 4551)
#
# User Stories:
#   US-CS-01  First sync with CONDSTORE server saves HIGHESTMODSEQ + UIDVALIDITY
#   US-CS-02  Second sync with unchanged modseq → "up to date" (no server traffic)
#   US-CS-03  Modseq changed → incremental sync: CHANGEDSINCE replaces SEARCH UNSEEN
#   US-CS-04  UIDVALIDITY changed → full resync, old sync state discarded
#   US-CS-05  No CONDSTORE → regular sync works; no sync_state file created
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 33: IMAP CONDSTORE incremental sync ---"

alloc_port CS_PORT
H_CS="./build/tests/functional/work-$$/homes/cs-$$"
CS_ACCT="condtest@imap.local"
CS_LOG="$H_CS/logs"
make_home "$H_CS" "$CS_ACCT" "$CS_PORT"
mkdir -p "$CS_LOG"

CS_DATA="$H_CS/.local/share/email-cli/accounts/$CS_ACCT"
CS_SYNC_STATE="$CS_DATA/sync_state/INBOX.tsv"

run_cs_sync() {
    (export HOME="$H_CS"
     unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     "$BIN_DIR/email-sync" 2>&1 || true)
}

# ── Phase 33a: first sync + up-to-date detection ──────────────────────────

(cd "$PROJECT_ROOT/build" && \
    MOCK_IMAP_PORT="$CS_PORT" \
    MOCK_IMAP_CAPS=CONDSTORE \
    MOCK_IMAP_UIDVAL=42 \
    MOCK_IMAP_MODSEQ=100 \
    MOCK_IMAP_COUNT=1 \
    "$MOCK_SERVER_BIN") >"$CS_LOG/mock_cs_a.log" 2>&1 &
CS_A_PID=$!
sleep 0.3

SYNC33A=$(run_cs_sync)

check "33.1 CONDSTORE first sync: message fetched" "fetched" "$SYNC33A"
check "33.2 CONDSTORE sync_state: uidvalidity saved" "42" \
    "$(cat "$CS_SYNC_STATE" 2>/dev/null || echo '')"
check "33.2b CONDSTORE sync_state: modseq saved" "100" \
    "$(cat "$CS_SYNC_STATE" 2>/dev/null || echo '')"

SYNC33A2=$(run_cs_sync)
check "33.3 CONDSTORE same modseq → up to date" "up to date" "$SYNC33A2"

kill "$CS_A_PID" 2>/dev/null || true
sleep 0.1

# ── Phase 33b: modseq changed → incremental sync ─────────────────────────

(cd "$PROJECT_ROOT/build" && \
    MOCK_IMAP_PORT=$CS_PORT \
    MOCK_IMAP_CAPS=CONDSTORE \
    MOCK_IMAP_UIDVAL=42 \
    MOCK_IMAP_MODSEQ=200 \
    MOCK_IMAP_COUNT=1 \
    MOCK_IMAP_CHANGED_COUNT=1 \
    "$MOCK_SERVER_BIN") >"$CS_LOG/mock_cs_b.log" 2>&1 &
CS_B_PID=$!
sleep 0.3

SYNC33B=$(run_cs_sync)
# Sync should run (not up to date) and process the change
check_not "33.4 CONDSTORE new modseq → not up to date" "up to date" "$SYNC33B"
# Mock log must show the CHANGEDSINCE command was sent
check "33.5 CONDSTORE incremental: CHANGEDSINCE command sent" \
    "CHANGEDSINCE" "$(cat "$CS_LOG/mock_cs_b.log" 2>/dev/null || echo '')"
# sync_state updated with new modseq
check "33.6 CONDSTORE sync_state updated to new modseq" "200" \
    "$(cat "$CS_SYNC_STATE" 2>/dev/null || echo '')"

kill "$CS_B_PID" 2>/dev/null || true
sleep 0.1

# ── Phase 33c: UIDVALIDITY changed → full resync ─────────────────────────

(cd "$PROJECT_ROOT/build" && \
    MOCK_IMAP_PORT=$CS_PORT \
    MOCK_IMAP_CAPS=CONDSTORE \
    MOCK_IMAP_UIDVAL=99 \
    MOCK_IMAP_MODSEQ=300 \
    MOCK_IMAP_COUNT=1 \
    "$MOCK_SERVER_BIN") >"$CS_LOG/mock_cs_c.log" 2>&1 &
CS_C_PID=$!
sleep 0.3

SYNC33C=$(run_cs_sync)
check "33.7 UIDVALIDITY changed → resync warning" "UIDVALIDITY" "$SYNC33C"
check "33.8 UIDVALIDITY changed → new uidval in sync_state" "99" \
    "$(cat "$CS_SYNC_STATE" 2>/dev/null || echo '')"

kill "$CS_C_PID" 2>/dev/null || true
rm -rf "./build/tests/functional/work-$$/homes/cs-$$"

# ── Phase 33d: no CONDSTORE → regular sync; no sync_state ────────────────

H_CS_D="./build/tests/functional/work-$$/homes/csd-$$"
make_home "$H_CS_D" "$CS_ACCT" "$CS_PORT"
CS_SYNC_STATE_D="$H_CS_D/.local/share/email-cli/accounts/$CS_ACCT/sync_state/INBOX.tsv"

(cd "$PROJECT_ROOT/build" && \
    MOCK_IMAP_PORT=$CS_PORT \
    MOCK_IMAP_COUNT=1 \
    "$MOCK_SERVER_BIN") >"$PROJECT_ROOT/build/tests/functional/work-$$/mock_cs_d.log" 2>&1 &
CS_D_PID=$!
sleep 0.3

SYNC33D=$( (export HOME="$H_CS_D"
     unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     "$BIN_DIR/email-sync" 2>&1 || true) )

check "33.9 no CONDSTORE → regular sync succeeds" "fetched\|stored" "$SYNC33D"
check "33.10 no CONDSTORE → no sync_state file" \
    "absent" "$(test -f "$CS_SYNC_STATE_D" && echo present || echo absent)"

kill "$CS_D_PID" 2>/dev/null || true
rm -rf "./build/tests/functional/work-$$/homes/csd-$$"

fi

if phase_wanted 34; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 34 — US-01: rules list command
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 34: rules list (US-01) ---"

H_RL="./build/tests/functional/work-$$/homes/rl-$$"
RL_ACCT="rules@test.local"
make_home "$H_RL" "$RL_ACCT" $IMAP1_PORT

# Write a rules.ini for the account
cat > "$H_RL/.config/email-cli/accounts/$RL_ACCT/rules.ini" <<'RINI'
[rule "GitHub notifications"]
if-from    = *@github.com
then-add-label    = GitHub
then-remove-label = INBOX

[rule "Newsletters"]
if-subject = *newsletter*
then-add-label    = Newsletters
then-move-folder  = INBOX.Newsletters

[rule "Spam patterns"]
if-from    = *@spammer.example
if-subject = *prize*
then-add-label    = _junk
RINI

RL_OUT=$( (export HOME="$H_RL"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )

check "34.1 rules list: count line (3 rules)"    "3 rule"            "$RL_OUT"
check "34.2 rules list: rule 1 name"             "GitHub"            "$RL_OUT"
check "34.3 rules list: from pattern shown"       "github.com"        "$RL_OUT"
check "34.4 rules list: then-add-label shown"    "then-add-label"    "$RL_OUT"
check "34.5 rules list: then-remove-label shown" "then-remove-label" "$RL_OUT"
check "34.6 rules list: rule 2 move-folder"      "then-move-folder"  "$RL_OUT"
check "34.7 rules list: multi-condition rule 3"  "Spam patterns"     "$RL_OUT"
check "34.8 rules list: subject pattern in rule 3" "newsletter\|prize" "$RL_OUT"

# Without subcommand ('rules' alone) must also list
RL_OUT2=$( (export HOME="$H_RL"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules 2>&1 || true) )
check "34.9 rules (no subcmd): same output"      "GitHub"            "$RL_OUT2"

# Empty case: no rules.ini
H_RL_EMPTY="./build/tests/functional/work-$$/homes/rl-empty-$$"
make_home "$H_RL_EMPTY" "$RL_ACCT" $IMAP1_PORT
RL_EMPTY=$( (export HOME="$H_RL_EMPTY"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )
check "34.10 rules list: no rules → helpful message" "No rules configured" "$RL_EMPTY"
check "34.11 rules list: no rules → hints at rules.ini path" "rules.ini\|import-rules" "$RL_EMPTY"

# Help pages
RL_HELP=$( "$BIN_DIR/email-cli" help rules 2>&1 || true )
check "34.12 help rules: usage line"   "rules list" "$RL_HELP"

RL_HELP2=$( "$BIN_DIR/email-cli" rules --help 2>&1 || true )
check "34.13 rules --help: usage line" "rules list" "$RL_HELP2"

rm -rf "./build/tests/functional/work-$$/homes/rl-$$"
rm -rf "./build/tests/functional/work-$$/homes/rl-empty-$$"

fi

if phase_wanted 35; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 35 — US-02: email-sync --verbose rules firing log
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 35: email-sync --verbose rules log (US-02) ---"

H_RV="./build/tests/functional/work-$$/homes/rv-$$"
RV_ACCT="rv@test.local"
make_home "$H_RV" "$RV_ACCT" $IMAP1_PORT

# Rule that matches the mock server's from address "Sender N <senderN@example.com>"
cat > "$H_RV/.config/email-cli/accounts/$RV_ACCT/rules.ini" <<'RVINI'
[rule "Mock messages"]
if-from = *@example.com*
then-add-label = MockLabel
RVINI

# Sync without --verbose: no per-rule lines expected
RV_QUIET=$( (export HOME="$H_RV"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-sync" 2>&1 || true) )
check_not "35.1 sync quiet: no [rule] lines without --verbose" "\[rule\]" "$RV_QUIET"
check     "35.2 sync quiet: fetched/stored summary present"    "fetched\|stored" "$RV_QUIET"

# Wipe local store so sync re-downloads messages for verbose test
rm -rf "$H_RV/.local/share/email-cli"

# Sync with --verbose: per-rule lines expected
RV_VERB=$( (export HOME="$H_RV"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-sync" --verbose 2>&1 || true) )
check "35.3 sync --verbose: [rule] line present"      "\[rule\]"      "$RV_VERB"
check "35.4 sync --verbose: rule name in output"      "Mock messages" "$RV_VERB"
check "35.5 sync --verbose: +label in rule log"       "+MockLabel"    "$RV_VERB"

# --apply-rules --verbose (US-02 apply path)
RV_ARULE=$( (export HOME="$H_RV"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-sync" --apply-rules --verbose 2>&1 || true) )
check "35.6 apply-rules --verbose: [rule] line"       "\[rule\]"      "$RV_ARULE"
check "35.7 apply-rules --verbose: rule name"         "Mock messages" "$RV_ARULE"

rm -rf "./build/tests/functional/work-$$/homes/rv-$$"

fi

if phase_wanted 36; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 36 — US-03/04: rules apply and rules apply --dry-run
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 36: rules apply / rules apply --dry-run (US-03/04) ---"

H_RA="./build/tests/functional/work-$$/homes/ra-$$"
RA_ACCT="ra@test.local"
make_home "$H_RA" "$RA_ACCT" $IMAP1_PORT

cat > "$H_RA/.config/email-cli/accounts/$RA_ACCT/rules.ini" <<'RAINI'
[rule "Tag alpha"]
if-from = *@example.com*
then-add-label = AlphaTag

[rule "Space flat"]
if-subject = *Msg (folded*
then-add-label = SpaceFlat

[rule "Space quoted"]
when = subject:"*Msg (folded*"
then-add-label = SpaceQuoted
RAINI

# First sync to populate local store
(export HOME="$H_RA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-sync" 2>&1 || true) > /dev/null

# dry-run: must NOT modify anything, must show what would change
RA_DRY=$( (export HOME="$H_RA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules apply --dry-run 2>&1 || true) )
check "36.1 rules apply --dry-run: [dry-run] marker present" "\[dry-run\]" "$RA_DRY"
check "36.2 rules apply --dry-run: rule name shown"          "Tag alpha"   "$RA_DRY"
check "36.3 rules apply --dry-run: dry-run summary"          "dry.run\|would be" "$RA_DRY"
# EMAIL-45: a glob with a space fires in the flat and in the quoted spelling
check "36.9 rules apply --dry-run: if-subject glob with a space fires"   "Space flat"   "$RA_DRY"
check "36.10 rules apply --dry-run: quoted when pattern with a space fires" "Space quoted" "$RA_DRY"

# Apply for real: must show [rule] lines and summary
RA_REAL=$( (export HOME="$H_RA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules apply --verbose 2>&1 || true) )
check "36.4 rules apply --verbose: [rule] line present"   "\[rule\]"        "$RA_REAL"
check "36.5 rules apply --verbose: rule name shown"       "Tag alpha"       "$RA_REAL"
check "36.6 rules apply: summary shows modified count"    "modified\|applied" "$RA_REAL"

# Second apply on same data: rules already applied → 0 changes
RA_AGAIN=$( (export HOME="$H_RA"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules apply 2>&1 || true) )
check_not "36.7 rules apply again: no messages to modify" "\[rule\]" "$RA_AGAIN"

# help page
RA_HELP=$( "$BIN_DIR/email-cli" help rules 2>&1 || true )
check "36.8 help rules: apply mentioned" "apply" "$RA_HELP"

rm -rf "./build/tests/functional/work-$$/homes/ra-$$"

fi

if phase_wanted 37; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 37 — US-05: rules add and rules remove
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 37: rules add / rules remove (US-05) ---"

H_RW="./build/tests/functional/work-$$/homes/rw-$$"
RW_ACCT="rw@test.local"
make_home "$H_RW" "$RW_ACCT" $IMAP1_PORT

# 37.1 Add first rule
ADD1=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules add \
        --name "GitHub" \
        --if-from "*@github.com" \
        --add-label GitHub \
        --remove-label INBOX \
        2>&1 || true) )
check "37.1 rules add: success message"  "added\|saved\|GitHub" "$ADD1"

# Verify it's stored
LIST1=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )
check "37.2 rules list after add: rule present"        "GitHub"          "$LIST1"
check "37.3 rules list after add: if-from condition"   "github.com"      "$LIST1"
check "37.4 rules list after add: then-add-label"      "then-add-label"  "$LIST1"
check "37.5 rules list after add: then-remove-label"   "then-remove-label" "$LIST1"

# 37.2 Add second rule (multiple --add-label)
(export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules add \
        --name "Newsletters" \
        --if-subject "*newsletter*" \
        --add-label Newsletters \
        --move-folder "INBOX.Newsletters" \
        2>&1 || true) > /dev/null

LIST2=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )
check "37.6 rules list: both rules present"          "2 rule"            "$LIST2"
check "37.7 rules list: second rule name"            "Newsletters"       "$LIST2"
check "37.8 rules list: move-folder in second rule"  "then-move-folder"  "$LIST2"

# 37.3 Duplicate name must fail
ADD_DUP=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules add --name "GitHub" --if-from "*@github.com" \
        2>&1 || true) )
check "37.9 rules add duplicate name: error"   "already exists\|duplicate\|Error" "$ADD_DUP"

# Verify count unchanged after duplicate attempt
LIST3=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )
check "37.10 rules list: still 2 rules after duplicate attempt" "2 rule" "$LIST3"

# 37.4 rules add --name is required
ADD_NONAME=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules add --if-from "*@test.com" 2>&1 || true) )
check "37.11 rules add without --name: error" "name\|required\|Error" "$ADD_NONAME"

# 37.5 rules remove
RM1=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules remove --name "GitHub" 2>&1 || true) )
check "37.12 rules remove: success message" "removed\|deleted\|GitHub" "$RM1"

LIST4=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules list 2>&1 || true) )
check     "37.13 rules list after remove: only 1 rule left"       "1 rule"  "$LIST4"
check_not "37.14 rules list after remove: removed rule gone"      "GitHub"  "$LIST4"
check     "37.15 rules list after remove: remaining rule present" "Newsletters" "$LIST4"

# 37.6 remove non-existent rule
RM_MISS=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules remove --name "NoSuchRule" 2>&1 || true) )
check "37.16 rules remove non-existent: error" "not found\|Error" "$RM_MISS"

# 37.7 rules remove --name is required
RM_NONAME=$( (export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" rules remove 2>&1 || true) )
check "37.17 rules remove without --name: error" "name\|required\|Error" "$RM_NONAME"

# help pages
check "37.18 help rules add: usage"    "rules add"    "$( "$BIN_DIR/email-cli" help rules 2>&1 || true )"
check "37.19 help rules remove: usage" "rules remove" "$( "$BIN_DIR/email-cli" help rules 2>&1 || true )"

# 37.8 rules edit: change a rule in place (EMAIL-127)
RE() { ( export HOME="$H_RW"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" "$@" 2>&1 || true ); }
RE rules add --name "Zeta" --if-from "*@zeta.test" --add-label Z1 --remove-label INBOX > /dev/null
RE rules add --name "Omega" --if-from "*@omega.test" --add-label O1 > /dev/null
ED1=$( RE rules edit --name "Zeta" --add-label Z2 --add-label Z3 )
check "37.20 rules edit: success message" "Rule updated" "$ED1"
ED_LIST=$( RE rules list )
check     "37.21 rules edit: new add-label present"       "Z2"        "$ED_LIST"
check_not "37.22 rules edit: old add-label replaced"      "Z1"        "$ED_LIST"
check     "37.23 rules edit: untouched condition kept"    "zeta.test" "$ED_LIST"
check     "37.24 rules edit: other rule untouched"        "omega.test" "$ED_LIST"
ED2=$( RE rules edit --name "Zeta" --if-subject "*sale*" --move-folder "INBOX.Sales" )
check "37.25 rules edit condition+folder: success" "Rule updated" "$ED2"
ED_LIST2=$( RE rules list )
check     "37.26 rules edit: new condition shown"         "sale"        "$ED_LIST2"
check_not "37.27 rules edit: old condition replaced"      "zeta.test"   "$ED_LIST2"
check     "37.28 rules edit: move-folder set"             "INBOX.Sales" "$ED_LIST2"
ED3=$( RE rules edit --name "Zeta" --new-name "Sales" )
check "37.29 rules edit --new-name: success" "Rule updated" "$ED3"
ED_LIST3=$( RE rules list )
check     "37.30 rules edit --new-name: new name listed"  "Sales"  "$ED_LIST3"
check_not "37.31 rules edit --new-name: old name gone"    "Zeta"   "$ED_LIST3"
check     "37.32 rules edit --new-name: still 3 rules"    "3 rule" "$ED_LIST3"
check     "37.33 rules edit: order kept (Sales before Omega)" "^ok$" \
    "$(echo "$ED_LIST3" | awk '/Sales/{s=NR} /Omega/{o=NR} END{print (s&&o&&s<o)?"ok":"bad"}')"
check "37.34 rules edit to an existing name: error" "already exists" \
    "$( RE rules edit --name "Sales" --new-name "Omega" )"
check "37.35 rules edit non-existent: error" "No rule named" "$( RE rules edit --name "NoSuch" --add-label X )"
check "37.36 rules edit without --name: error" "name.*required\|required" "$( RE rules edit --add-label X )"
check "37.37 rules edit with nothing to change: error" "nothing to change" "$( RE rules edit --name "Sales" )"
check "37.38 rules edit --help: usage" "rules edit --name" "$( RE rules edit --help )"
check "37.39 help rules edit: usage"   "rules edit --name" "$( RE help rules edit )"
ED4=$( RE rules edit --name "Sales" --move-folder "" )
RE_LIST4=$( RE rules list | awk '/Sales/{f=1;next} /Omega/{f=0} f' )
check_not "37.40 rules edit --move-folder \"\": folder cleared" "INBOX.Sales" "$RE_LIST4"

rm -rf "./build/tests/functional/work-$$/homes/rw-$$"

fi

if phase_wanted 38; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 38 — email-import-rules: bin presence + unsupported rule warnings
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 38: email-import-rules (US-IR-01 / US-IR-02) ---"

# US-IR-01: email-import-rules must be present in bin/
check "38.1 email-import-rules binary exists in bin/" "^ok$" \
    "$(test -x "$BIN_DIR/email-import-rules" && echo ok || echo missing)"

# US-IR-02: unsupported Thunderbird rule elements produce [warn] lines on stderr

# Create a synthetic Thunderbird profile with mixed supported/unsupported rules
TB_DIR="./build/tests/functional/work-$$/homes/tb-$$"
mkdir -p "$TB_DIR/ImapMail/localhost"
make_tb_prefs "$TB_DIR" "localhost" "ir@test.local" "localhost"
cat > "$TB_DIR/ImapMail/localhost/msgFilterRules.dat" <<'TBDAT'
version="9"
logging="no"
name="Good rule"
enabled="yes"
condition="AND (from,contains,@github.com)"
action="Move to folder"
actionValue="imap://user@imap.test.local/GitHub"

name="Bad body rule"
enabled="yes"
condition="AND (body,contains,newsletter)"
action="Label"
actionValue="$label1"

name="Mixed conditions"
enabled="yes"
condition="AND (from,contains,@example.com) (age,greater than,7)"
action="Move to folder"
actionValue="imap://user@imap.test.local/Archive"

name="Doesnt contain rule"
enabled="yes"
condition="AND (from,doesn't contain,spam)"
action="Move to folder"
actionValue="imap://user@imap.test.local/NotSpam"

name="Isnt rule"
enabled="yes"
condition="AND (subject,isn't,Unsubscribe)"
action="Move to folder"
actionValue="imap://user@imap.test.local/Regular"

name="All niche unsupported"
enabled="yes"
condition="AND (cc,contains,@example.com)"
action="Copy to folder"
actionValue="imap://user@imap.test.local/CC"

name="Junk rule"
enabled="yes"
condition="AND (from,contains,@spam.example.com)"
action="Mark as junk"

name="Delete rule"
enabled="yes"
condition="AND (subject,contains,Virus)"
action="Delete"

name="Starred rule"
enabled="yes"
condition="AND (from,contains,@vip.example.com)"
action="Mark as starred"

name="Read rule"
enabled="yes"
condition="AND (from,contains,@newsletter.example.com)"
action="Mark as read"

name="Label work rule"
enabled="yes"
condition="AND (from,contains,@company.example.com)"
action="Label"
actionValue="$label2"

name="Niche fields"
enabled="yes"
condition="AND (to or cc,contains,@example.com) (size,greater than,100) (has attachment,is,true) (date,is before,2020-01-01)"
action="Move to folder"
actionValue="imap://user@imap.test.local/Niche"

name="Address book match"
enabled="yes"
condition="AND (from,is in ab,Personal)"
action="Move to folder"
actionValue="imap://user@imap.test.local/Contacts"

name="Stop processing"
enabled="yes"
condition="AND (subject,contains,Bulk)"
action="Stop filter evaluation"

TBDAT

# We need an account for the importer; use a dummy config
H_IR="./build/tests/functional/work-$$/homes/ir-$$"
mkdir -p "$H_IR/.config/email-cli/accounts/ir@test.local"
cat > "$H_IR/.config/email-cli/accounts/ir@test.local/config.ini" <<CFG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=ir@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CFG

IR_OUT=$( (export HOME="$H_IR"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-import-rules" --thunderbird-path "$TB_DIR" \
        --account ir@test.local --dry-run 2>&1 || true) )

# Good rule should be converted successfully (visible in stdout output)
check "38.2 good rule converted: rule name present"       "Good rule"         "$IR_OUT"
check "38.3 good rule converted: if-from shown"           "github.com"        "$IR_OUT"
check "38.4 good rule converted: move-folder shown"       "GitHub"            "$IR_OUT"

# Still-unsupported conditions/actions emit [warn] lines (US-64/US-74)
check_not "38.5 no warn for body (US-69 implemented)"     "\[warn\].*body"    "$IR_OUT"
check "38.6 warn for unsupported action (Copy to folder)" "\[warn\].*Copy"    "$IR_OUT"
check "38.7 warn for empty rule (niche: cc + Copy)"       "no conditions\|no.*actions\|could be converted\|will be empty" "$IR_OUT"
check_not "38.8 no warn for age (US-70 implemented)"      "\[warn\].*age"     "$IR_OUT"
check_not "38.9 no warn for doesn't contain (US-68)"      "\[warn\].*doesn"   "$IR_OUT"

# BUG-001 fix verified: "isn't" now converts (no warn) instead of silently becoming positive match
check_not "38.12 no warn for isn't (BUG-001+US-68)"       "\[warn\].*isn"     "$IR_OUT"

# US-66: flag actions converted (no warn emitted)
check "38.13 Mark as junk → then-add-label = _junk"       "_junk"             "$IR_OUT"
check "38.14 Delete → then-add-label = _trash"            "_trash"            "$IR_OUT"
check "38.15 Mark as starred → then-add-label = _flagged" "_flagged"          "$IR_OUT"
check "38.16 Mark as read → then-remove-label = UNREAD"   "UNREAD"            "$IR_OUT"
check_not "38.17 no warn for Mark as junk (US-66)"        "\[warn\].*junk"    "$IR_OUT"
check_not "38.18 no warn for Delete (US-66)"              "\[warn\].*Delete"  "$IR_OUT"
check_not "38.19 no warn for Mark as starred (US-66)"     "\[warn\].*starred" "$IR_OUT"
check_not "38.20 no warn for Mark as read (US-66)"        "\[warn\].*read"    "$IR_OUT"

# US-67: Label action converted to named label (no warn emitted)
check "38.21 Label \$label2 → then-add-label = Work"      "Work"              "$IR_OUT"
check_not "38.22 no warn for Label action (US-67)"        "\[warn\].*Label"   "$IR_OUT"

# US-74 / TASK-001: niche Thunderbird elements that remain unsupported must warn.
# Condition fields (the field check runs before the match-type check, so an
# unsupported field always reports the field, never the match type).
check "38.23 warn for unsupported field (to or cc)"       "\[warn\].*to or cc"     "$IR_OUT"
check "38.24 warn for unsupported field (size)"           "\[warn\].*size"         "$IR_OUT"
check "38.25 warn for unsupported field (has attachment)" "\[warn\].*attachment"   "$IR_OUT"
check "38.26 warn for unsupported field (date)"           "\[warn\].*date"         "$IR_OUT"
# Match type on a *supported* field: reports the match type itself.
check "38.27 warn for unsupported match type (is in ab)"  "\[warn\].*is in ab"     "$IR_OUT"
# Actions
check "38.28 warn for unsupported action (Stop filter)"   "\[warn\].*Stop filter"  "$IR_OUT"
# Skipped terms are dropped, but the rule's convertible action is still kept.
check "38.29 niche rule kept with its action"             "then-move-folder  = Niche"   "$IR_OUT"
check_not "38.30 skipped niche term absent from when"     "when.*to or cc"             "$IR_OUT"

# The --help output must mention the binary name
IR_HELP=$( "$BIN_DIR/email-import-rules" --help 2>&1 || true )
check "38.10 help: usage line"                            "email-import-rules" "$IR_HELP"
check "38.11 help: --thunderbird-path option"             "thunderbird-path"   "$IR_HELP"

rm -rf "./build/tests/functional/work-$$/homes/ir-$$"
case "$TB_DIR" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe TB_DIR path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/${TB_DIR##./build/tests/functional/work-$$/homes/}"

fi

