SSL_NO_VERIFY=1
INI
chmod 0600 "$ATTACH_CFG/config.ini"
ATTACH_TXT=$(mktemp "$WORK_DIR/attach-file-XXXXXX.txt")
echo "Attachment content" > "$ATTACH_TXT"
ATTACH_PDF=$(mktemp "$WORK_DIR/attach-file-XXXXXX.pdf")
printf '%%PDF-1.4 stub\n' > "$ATTACH_PDF"

# 79.1: send with --attach → succeeds (mock SMTP accepts)
OUT79_1=$("$BIN_DIR/email-cli" -q send \
    --to alice@example.com \
    --subject "Attach test" \
    --body "See attached" \
    --attach "$ATTACH_TXT" 2>&1 || true)
check "79.1 send --attach: success" "sent\|Sent\|queued" "$OUT79_1"

# 79.2: send with multiple --attach flags
OUT79_2=$("$BIN_DIR/email-cli" -q send \
    --to alice@example.com \
    --subject "Multi-attach test" \
    --body "Two files" \
    --attach "$ATTACH_TXT" \
    --attach "$ATTACH_PDF" 2>&1 || true)
check "79.2 send --attach --attach: success" "sent\|Sent\|queued" "$OUT79_2"

# 79.3: --attach with non-existent file → error
OUT79_3=$("$BIN_DIR/email-cli" -q send \
    --to alice@example.com \
    --subject "Bad attach" \
    --body "body" \
    --attach "$WORK_DIR/no-such-file-xyz-404.pdf" 2>&1 || true)
check "79.3 send --attach non-existent: error" "not found\|No such file\|Error" "$OUT79_3"

# 79.4: --attach with directory path → error
OUT79_4=$("$BIN_DIR/email-cli" -q send \
    --to alice@example.com \
    --subject "Dir attach" \
    --body "body" \
    --attach "$WORK_DIR/" 2>&1 || true)
check "79.4 send --attach directory: error" "Not a file\|directory\|Error" "$OUT79_4"

# 79.5: --attach exceeding 25 MB limit → error
BIGFILE=$(mktemp "$WORK_DIR/attach-big-XXXXXX.bin")
dd if=/dev/zero of="$BIGFILE" bs=1M count=26 2>/dev/null
OUT79_5=$("$BIN_DIR/email-cli" -q send \
    --to alice@example.com \
    --subject "Big attach" \
    --body "body" \
    --attach "$BIGFILE" 2>&1 || true)
check "79.5 send --attach >25MB: size error" "too large\|exceeds\|25\|Error" "$OUT79_5"
rm -f "$BIGFILE" "$ATTACH_TXT" "$ATTACH_PDF"
export HOME="$H_ALPHA"

fi

if phase_wanted 80; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 80: DMARC status in message list
# ════════════════════════════════════════════════════════════════════════════
echo "--- Phase 80: DMARC status in message list ---"
alloc_port DMARC_PORT
H_DMARC="./build/tests/functional/work-$$/homes/dmarc"

# 80.1: dmarc=pass — status column shows 'v'
echo "Starting mock IMAP for Phase 80.1 (dmarc=pass, port $DMARC_PORT)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$DMARC_PORT \
    MOCK_IMAP_COUNT=3 MOCK_IMAP_DMARC=pass \
    "$MOCK_SERVER_BIN") >/dev/null 2>&1 &
DMARC_PID=$!
sleep 0.3
make_home "$H_DMARC" "dmarc@example.com" "$DMARC_PORT"
export HOME="$H_DMARC"
OUT80_1=$(HOME="$H_DMARC" "$BIN_DIR/email-cli" list 2>&1 || true)
check "80.1 dmarc=pass: status shows v" "N----v" "$OUT80_1"

# 80.2: second run from same HOME — DMARC_CHECKED cached, still shows 'v'
OUT80_2=$(HOME="$H_DMARC" "$BIN_DIR/email-cli" list 2>&1 || true)
check "80.2 dmarc=pass cached: status still shows v" "N----v" "$OUT80_2"

kill "$DMARC_PID" 2>/dev/null; wait "$DMARC_PID" 2>/dev/null || true
sleep 0.2

# 80.3: dmarc=fail — status column shows 'x'
echo "Starting mock IMAP for Phase 80.3 (dmarc=fail, port $DMARC_PORT)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$DMARC_PORT \
    MOCK_IMAP_COUNT=3 MOCK_IMAP_DMARC=fail \
    "$MOCK_SERVER_BIN") >/dev/null 2>&1 &
DMARC_PID=$!
sleep 0.3
make_home "$H_DMARC" "dmarc@example.com" "$DMARC_PORT"
export HOME="$H_DMARC"
OUT80_3=$(HOME="$H_DMARC" "$BIN_DIR/email-cli" list 2>&1 || true)
check "80.3 dmarc=fail: status shows x" "N----x" "$OUT80_3"
kill "$DMARC_PID" 2>/dev/null; wait "$DMARC_PID" 2>/dev/null || true
sleep 0.2

# 80.4: no Authentication-Results — last status char is '-'
echo "Starting mock IMAP for Phase 80.4 (no DMARC, port $DMARC_PORT)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$DMARC_PORT \
    MOCK_IMAP_COUNT=3 \
    "$MOCK_SERVER_BIN") >/dev/null 2>&1 &
DMARC_PID=$!
sleep 0.3
make_home "$H_DMARC" "dmarc@example.com" "$DMARC_PORT"
export HOME="$H_DMARC"
OUT80_4=$(HOME="$H_DMARC" "$BIN_DIR/email-cli" list 2>&1 || true)
check     "80.4 no DMARC: status shows N-----" "N-----" "$OUT80_4"
check_not "80.4 no DMARC: no v in status"      "N----v" "$OUT80_4"
check_not "80.4 no DMARC: no x in status"      "N----x" "$OUT80_4"
kill "$DMARC_PID" 2>/dev/null; wait "$DMARC_PID" 2>/dev/null || true

export HOME="$H_ALPHA"

fi

if phase_wanted 81; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 81 — Forward: __forwarded__ virtual folder with pre-seeded manifests
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 81: forward virtual folder ---"

H_FWD81="./build/tests/functional/work-$$/homes/fwd81"
rm -rf "./build/tests/functional/work-$$/homes/fwd81"
mkdir -p "$H_FWD81/.config/email-cli/accounts/fwd81@test.local"
cat > "$H_FWD81/.config/email-cli/accounts/fwd81@test.local/config.ini" <<CFG81
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=fwd81@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CFG81
mkdir -p "$H_FWD81/.local/share/email-cli/accounts/fwd81@test.local/manifests"
# MSG_FLAG_FORWARDED = 32 (1 << 5); MSG_FLAG_UNSEEN = 1
printf "0000000000000001\tSender1 <s1@fwd.test>\tFwdSubjA\t2024-01-01 10:00\t32\n" \
    > "$H_FWD81/.local/share/email-cli/accounts/fwd81@test.local/manifests/INBOX.tsv"
printf "0000000000000002\tSender2 <s2@fwd.test>\tUnreadOnlySubj\t2024-01-02 10:00\t1\n" \
    >> "$H_FWD81/.local/share/email-cli/accounts/fwd81@test.local/manifests/INBOX.tsv"
printf "0000000000000003\tSender3 <s3@fwd.test>\tFwdSubjB\t2024-01-03 10:00\t32\n" \
    > "$H_FWD81/.local/share/email-cli/accounts/fwd81@test.local/manifests/INBOX.Sent.tsv"

OUT81_1=$(HOME="$H_FWD81" "$BIN_DIR/email-cli" --batch list --folder __forwarded__ 2>&1 || true)
check_not "81.1 forwarded folder: no crash"              "Segmentation\|Abort" "$OUT81_1"
check     "81.2 forwarded folder: 2 forwarded messages"  "2 message"           "$OUT81_1"
check     "81.3 forwarded folder: FwdSubjA shown"        "FwdSubjA"            "$OUT81_1"
check     "81.4 forwarded folder: FwdSubjB shown"        "FwdSubjB"            "$OUT81_1"
check_not "81.5 forwarded folder: unread-only not shown" "UnreadOnlySubj"      "$OUT81_1"

export HOME="$H_ALPHA"

fi

if phase_wanted 82; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 82 — Dedup: same UID in multiple manifests appears only once
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 82: virtual folder dedup ---"

H_DUP82="./build/tests/functional/work-$$/homes/dup82"
rm -rf "./build/tests/functional/work-$$/homes/dup82"
mkdir -p "$H_DUP82/.config/email-cli/accounts/dup82@test.local"
cat > "$H_DUP82/.config/email-cli/accounts/dup82@test.local/config.ini" <<CFG82
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=dup82@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CFG82
mkdir -p "$H_DUP82/.local/share/email-cli/accounts/dup82@test.local/manifests"
# MSG_FLAG_FLAGGED = 2 (1 << 1)
# INBOX.tsv: UID 1 (flagged), UID 2 (flagged)
printf "0000000000000001\tDupSend1 <d1@dup.test>\tDupSubj1\t2024-01-01 10:00\t2\n" \
    > "$H_DUP82/.local/share/email-cli/accounts/dup82@test.local/manifests/INBOX.tsv"
printf "0000000000000002\tDupSend2 <d2@dup.test>\tDupSubj2\t2024-01-02 10:00\t2\n" \
    >> "$H_DUP82/.local/share/email-cli/accounts/dup82@test.local/manifests/INBOX.tsv"
# INBOX.Sent.tsv: UID 1 (DUPLICATE of INBOX UID 1), UID 3 (unique)
printf "0000000000000001\tDupSend1 <d1@dup.test>\tDupSubj1\t2024-01-01 10:00\t2\n" \
    > "$H_DUP82/.local/share/email-cli/accounts/dup82@test.local/manifests/INBOX.Sent.tsv"
printf "0000000000000003\tDupSend3 <d3@dup.test>\tDupSubj3\t2024-01-03 10:00\t2\n" \
    >> "$H_DUP82/.local/share/email-cli/accounts/dup82@test.local/manifests/INBOX.Sent.tsv"

OUT82_1=$(HOME="$H_DUP82" "$BIN_DIR/email-cli" --batch list --folder __flagged__ 2>&1 || true)
check_not "82.1 dedup flagged: no crash"                  "Segmentation\|Abort" "$OUT82_1"
check     "82.2 dedup flagged: 3 unique messages (not 4)" "3 message"           "$OUT82_1"
check     "82.3 dedup flagged: DupSubj1 shown"            "DupSubj1"            "$OUT82_1"
check     "82.4 dedup flagged: DupSubj2 shown"            "DupSubj2"            "$OUT82_1"
check     "82.5 dedup flagged: DupSubj3 shown"            "DupSubj3"            "$OUT82_1"
DUP82_CNT=$(echo "$OUT82_1" | grep -c "DupSubj1" || true)
check     "82.6 dedup flagged: DupSubj1 appears only once" "^1$" "$DUP82_CNT"

export HOME="$H_ALPHA"

fi

