if phase_wanted 84; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 84 — list filters (--from/--since/--before), __all__ and --json
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 84: list filters, __all__, JSON output ---"

H_F84="./build/tests/functional/work-$$/homes/f84"
rm -rf "./build/tests/functional/work-$$/homes/f84"
mkdir -p "$H_F84/.config/email-cli/accounts/f84@test.local"
cat > "$H_F84/.config/email-cli/accounts/f84@test.local/config.ini" <<CFG84
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=f84@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
SYNC_INTERVAL=5
CFG84
M84="$H_F84/.local/share/email-cli/accounts/f84@test.local/manifests"
mkdir -p "$M84"
# uid \t from \t subject \t date \t flags   (1 = MSG_FLAG_UNSEEN)
{
  printf "0000000000000001\tAlice <alice@shop.example>\tOrderAlpha\t2024-01-10 10:00\t1\n"
  printf "0000000000000002\tBob <bob@other.example>\tOrderBeta\t2024-03-15 10:00\t0\n"
} > "$M84/INBOX.tsv"
printf "0000000000000003\tAlice <alice@shop.example>\tSentGamma\t2024-02-20 10:00\t0\n" > "$M84/INBOX.Sent.tsv"

f84() { (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
         "$BIN_DIR/email-cli-ro" --batch list --all "$@" 2>&1 || true); }

# --from: case-insensitive substring on the From field
OUT84_1=$(f84 --from alice)
check     "84.1 --from matches sender"            "OrderAlpha"  "$OUT84_1"
check_not "84.2 --from excludes other senders"    "OrderBeta"   "$OUT84_1"
OUT84_2=$(f84 --from ALICE)
check     "84.3 --from is case-insensitive"       "OrderAlpha"  "$OUT84_2"

# --since is inclusive, --before is exclusive
OUT84_3=$(f84 --since 2024-03-15)
check     "84.4 --since includes the bound day"   "OrderBeta"   "$OUT84_3"
check_not "84.5 --since drops earlier mail"       "OrderAlpha"  "$OUT84_3"
OUT84_4=$(f84 --before 2024-03-15)
check     "84.6 --before keeps earlier mail"      "OrderAlpha"  "$OUT84_4"
check_not "84.7 --before excludes the bound day"  "OrderBeta"   "$OUT84_4"

# Filters combine
OUT84_5=$(f84 --from alice --since 2024-01-01 --before 2024-02-01)
check     "84.8 combined filters match"           "OrderAlpha"  "$OUT84_5"
check_not "84.9 combined filters exclude"         "OrderBeta"   "$OUT84_5"

# Invalid date is rejected, not silently ignored
OUT84_6=$( (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --since 2024/01/01 2>&1 || true) )
check     "84.10 invalid --since rejected"        "YYYY-MM-DD"  "$OUT84_6"

# __all__ spans folders; a plain listing does not
OUT84_7=$(f84 --folder __all__)
check     "84.11 __all__ includes INBOX mail"     "OrderAlpha"  "$OUT84_7"
check     "84.12 __all__ includes other folders"  "SentGamma"   "$OUT84_7"
OUT84_8=$(f84)
check_not "84.13 plain list stays in one folder"  "SentGamma"   "$OUT84_8"

# --json: parseable, complete, and free of decoration
OUT84_9=$(f84 --json)
check     "84.14 json: opens an array"            "^\["        "$OUT84_9"
check     "84.15 json: has uid field"             "\"uid\""     "$OUT84_9"
check     "84.16 json: has boolean unread"        "\"unread\": \(true\|false\)" "$OUT84_9"
check_not "84.17 json: no count line on stdout"   "message(s) in" "$OUT84_9"
JSON_OK=$(printf '%s' "$OUT84_9" | python3 -c "
import json,sys
try:
    d = json.load(sys.stdin)
    print('PARSED', len(d))
except Exception as e:
    print('BROKEN', e)
" 2>/dev/null || echo "BROKEN")
check     "84.18 json: stdout parses as JSON"     "PARSED 2"    "$JSON_OK"

# --json with no matches is still a valid empty array
OUT84_10=$(f84 --json --from zzznomatch)
JSON_EMPTY=$(printf '%s' "$OUT84_10" | python3 -c "
import json,sys
try:
    print('EMPTY' if json.load(sys.stdin) == [] else 'NONEMPTY')
except Exception:
    print('BROKEN')
" 2>/dev/null || echo "BROKEN")
check     "84.19 json: empty result is []"        "EMPTY"       "$JSON_EMPTY"

# --json for an uncached folder: still valid JSON, advice on stderr
OUT84_11=$( (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --all --json --folder INBOX.Missing 2>/dev/null || true) )
JSON_MISS=$(printf '%s' "$OUT84_11" | python3 -c "
import json,sys
try:
    print('EMPTY' if json.load(sys.stdin) == [] else 'NONEMPTY')
except Exception:
    print('BROKEN')
" 2>/dev/null || echo "BROKEN")
check     "84.20 json: uncached folder yields []" "EMPTY"       "$JSON_MISS"
OUT84_12=$( (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --all --json --folder INBOX.Missing 2>&1 >/dev/null || true) )
check     "84.21 json: advice goes to stderr"     "No cached data" "$OUT84_12"

# The same options exist on the read-write binary
OUT84_13=$( (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" --batch list --all --from alice 2>&1 || true) )
check     "84.22 email-cli has the same filters"  "OrderAlpha"  "$OUT84_13"

# Help documents them
OUT84_14=$( "$BIN_DIR/email-cli-ro" help list 2>&1 || true )
check     "84.23 help documents --from"           "\-\-from"    "$OUT84_14"
check     "84.24 help documents --json"           "\-\-json"    "$OUT84_14"
check     "84.25 help documents __all__"          "__all__"     "$OUT84_14"

# --all-accounts: every configured account, each under its own heading
H_F84B="./build/tests/functional/work-$$/homes/f84b"
rm -rf "./build/tests/functional/work-$$/homes/f84b"
for acct in first@test.local second@test.local; do
    mkdir -p "$H_F84B/.config/email-cli/accounts/$acct"
    cat > "$H_F84B/.config/email-cli/accounts/$acct/config.ini" <<CFGB
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=$acct
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
SYNC_INTERVAL=5
CFGB
    mkdir -p "$H_F84B/.local/share/email-cli/accounts/$acct/manifests"
done
printf "0000000000000010\tSender One <one@x.test>\tSubjectOne\t2024-01-01 10:00\t1\n" \
    > "$H_F84B/.local/share/email-cli/accounts/first@test.local/manifests/INBOX.tsv"
printf "0000000000000020\tSender Two <two@x.test>\tSubjectTwo\t2024-01-02 10:00\t1\n" \
    > "$H_F84B/.local/share/email-cli/accounts/second@test.local/manifests/INBOX.tsv"

OUT84_15=$( (export HOME="$H_F84B"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --all --all-accounts 2>&1 || true) )
check "84.26 --all-accounts lists first account"  "SubjectOne"        "$OUT84_15"
check "84.27 --all-accounts lists second account" "SubjectTwo"        "$OUT84_15"
check "84.28 --all-accounts prints headings"      "=== first@test.local ===" "$OUT84_15"

# Without the flag, several accounts are ambiguous and the command refuses
OUT84_16=$( (export HOME="$H_F84B"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --all 2>&1 || true) )
check "84.29 without the flag multiple accounts error" "Multiple accounts" "$OUT84_16"

# --all-accounts with --json is refused rather than emitting several documents
OUT84_17=$( (export HOME="$H_F84B"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --all --all-accounts --json 2>&1 || true) )
check "84.30 --all-accounts + --json refused"     "cannot be combined" "$OUT84_17"
check "84.31 refusal suggests a shell loop"       "list-accounts"      "$OUT84_17"

OUT84_18=$( "$BIN_DIR/email-cli-ro" help list 2>&1 || true )
check "84.32 help documents --all-accounts"       "\-\-all-accounts"  "$OUT84_18"

# The same options through email-cli itself (the shared read code, the
# read-write binary): a mutation of one front end must not go unnoticed.
f84rw() { (export HOME="$H_F84"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
           "$BIN_DIR/email-cli" --batch list --all "$@" 2>&1 || true); }
OUTRW=$(f84rw --from alice)
check     "84.33 email-cli --from matches sender"          "OrderAlpha" "$OUTRW"
check_not "84.34 email-cli --from excludes other senders"  "OrderBeta"  "$OUTRW"
OUTRW=$(f84rw --since 2024-03-15)
check     "84.35 email-cli --since includes the bound day" "OrderBeta"  "$OUTRW"
check_not "84.36 email-cli --since drops earlier mail"     "OrderAlpha" "$OUTRW"
OUTRW=$(f84rw --before 2024-03-15)
check     "84.37 email-cli --before keeps earlier mail"    "OrderAlpha" "$OUTRW"
check_not "84.38 email-cli --before excludes the bound day" "OrderBeta" "$OUTRW"
OUTRW=$(f84rw --json)
check_not "84.39 email-cli --json: no count line on stdout" "message(s) in" "$OUTRW"
JSON_RW=$(printf '%s' "$OUTRW" | python3 -c "
import json,sys
try:
    d = json.load(sys.stdin)
    print('PARSED', len(d), d[0].get('uid') is not None)
except Exception as e:
    print('BROKEN', e)
" || echo "BROKEN")
check     "84.40 email-cli --json parses with the uid field" "PARSED 2 True" "$JSON_RW"
OUTRW=$( (export HOME="$H_F84B"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" --batch list --all --all-accounts 2>&1 || true) )
check     "84.41 email-cli --all-accounts lists first account"  "SubjectOne" "$OUTRW"
check     "84.42 email-cli --all-accounts lists second account" "SubjectTwo" "$OUTRW"
check     "84.43 email-cli --all-accounts prints headings" "=== second@test.local ===" "$OUTRW"

export HOME="$H_ALPHA"


fi

if phase_wanted 85; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 85 — body search decodes; show locates the folder itself
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 85: decoded body search, folder-less show ---"

H_F85="./build/tests/functional/work-$$/homes/f85"
rm -rf "./build/tests/functional/work-$$/homes/f85"
mkdir -p "$H_F85/.config/email-cli/accounts/f85@test.local"
cat > "$H_F85/.config/email-cli/accounts/f85@test.local/config.ini" <<CFG85
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=f85@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
SYNC_INTERVAL=5
CFG85
D85="$H_F85/.local/share/email-cli/accounts/f85@test.local"
mkdir -p "$D85/manifests" "$D85/store/vasarlas/7/3" "$D85/store/vasarlas/8/3"

# UID 837: latin-2 body — the accented words are NOT UTF-8 in the file.
printf 'From: shop@x.hu\r\nSubject: Megrendeles\r\nDate: Mon, 1 Jan 2024 10:00:00 +0000\r\nContent-Type: text/plain; charset=iso-8859-2\r\n\r\nComputherm DS5-25 m\xe1gneses iszaplev\xe1laszt\xf3 1 db\r\n' \
    > "$D85/store/vasarlas/7/3/0000000000000837.eml"
# UID 838: base64 body — opaque unless the searcher decodes it.
B64_85=$(printf 'Szallitasi ertesito: iszaplevalaszto uton van.' | base64 -w0)
printf 'From: shop@x.hu\r\nSubject: Szallitas\r\nDate: Mon, 2 Jan 2024 10:00:00 +0000\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n%s\r\n' \
    "$B64_85" > "$D85/store/vasarlas/8/3/0000000000000838.eml"
{
  printf "0000000000000837\tshop@x.hu\tMegrendeles\t2024-01-01 10:00\t0\n"
  printf "0000000000000838\tshop@x.hu\tSzallitas\t2024-01-02 10:00\t0\n"
} > "$D85/manifests/vasarlas.tsv"

f85() { (export HOME="$H_F85"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
         "$BIN_DIR/email-cli-ro" --batch "$@" 2>&1 || true); }

# ASCII inside a latin-2 message was always findable — the regression guard.
OUT85_1=$(f85 list --folder "__search__:3:Computherm")
check "85.1 body search finds ASCII in latin-2 mail"   "Megrendeles" "$OUT85_1"

# The real defect: an accented word stored in iso-8859-2 must match a UTF-8
# query, which only works if the search decodes like `show` does.
OUT85_3=$( (export HOME="$H_F85"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli-ro" --batch list --folder "__search__:3:mágneses" 2>&1 || true) )
check "85.2 body search matches accented latin-2 text" "Megrendeles" "$OUT85_3"

# base64 bodies are opaque without transfer-decoding
OUT85_4=$(f85 list --folder "__search__:3:ertesito")
check "85.3 body search decodes base64 bodies"        "Szallitas"   "$OUT85_4"

# A query that appears nowhere must still report nothing
OUT85_5=$(f85 list --folder "__search__:3:zzznosuchword")
check_not "85.4 body search: no false positives"      "Megrendeles" "$OUT85_5"

# show without --folder: the UID lives in "vasarlas", not the configured INBOX
OUT85_6=$(f85 show 837)
check "85.4b show locates the folder itself"          "Megrendeles" "$OUT85_6"
check "85.5 show decodes the latin-2 body"            "mágneses"    "$OUT85_6"

# General help must advertise the search, filters and JSON
OUT85_7=$( "$BIN_DIR/email-cli-ro" --help 2>&1 || true )
check "85.6 general help mentions search"   "__search__"      "$OUT85_7"
check "85.7 general help mentions --json"   "\-\-json"        "$OUT85_7"
check "85.8 general help mentions --from"   "\-\-from"        "$OUT85_7"
OUT85_8=$( "$BIN_DIR/email-cli" help send 2>&1 || true )
check "85.9 send help documents --attach"   "\-\-attach"      "$OUT85_8"

export HOME="$H_ALPHA"

fi

if phase_wanted 86; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 86 — one UID in several folders: no silent wrong answer
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 86: cross-folder UID ambiguity, folder column ---"

H_F86="./build/tests/functional/work-$$/homes/f86"
rm -rf "./build/tests/functional/work-$$/homes/f86"
mkdir -p "$H_F86/.config/email-cli/accounts/f86@test.local"
cat > "$H_F86/.config/email-cli/accounts/f86@test.local/config.ini" <<CFG86
EMAIL_HOST=imaps://localhost:$DEAD_PORT
EMAIL_USER=f86@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=Archive
SSL_NO_VERIFY=1
SYNC_INTERVAL=5
CFG86
D86="$H_F86/.local/share/email-cli/accounts/f86@test.local"
mkdir -p "$D86/manifests" "$D86/store/Inbox/7/3" "$D86/store/INBOX/7/3" \
         "$D86/store/vasarlas/7/3" "$D86/store/Trash/9/3"

# The SAME UID in three real folders, each with different content, plus an
# "Inbox"/"INBOX" pair that RFC 3501 says is a single mailbox.
mk86() { printf 'From: %s\r\nSubject: %s\r\nDate: Mon, 1 Jan 2024 10:00:00 +0000\r\n\r\nbody %s\r\n' "$2" "$3" "$3" > "$1"; }
mk86 "$D86/store/Inbox/7/3/0000000000000837.eml"    a@x.hu InboxCopy
cp   "$D86/store/Inbox/7/3/0000000000000837.eml" "$D86/store/INBOX/7/3/0000000000000837.eml"
mk86 "$D86/store/vasarlas/7/3/0000000000000837.eml" shop@x.hu OrderCopy
mk86 "$D86/store/Trash/9/3/0000000000000839.eml"    z@x.hu TrashOnly
printf "0000000000000837\ta@x.hu\tInboxCopy\t2024-01-01 10:00\t0\n"    > "$D86/manifests/Inbox.tsv"
cp "$D86/manifests/Inbox.tsv" "$D86/manifests/INBOX.tsv"
printf "0000000000000837\tshop@x.hu\tOrderCopy\t2024-01-01 10:00\t0\n" > "$D86/manifests/vasarlas.tsv"
printf "0000000000000839\tz@x.hu\tTrashOnly\t2024-01-01 10:00\t0\n"    > "$D86/manifests/Trash.tsv"

f86() { (export HOME="$H_F86"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
         "$BIN_DIR/email-cli-ro" --batch "$@" 2>&1 || true); }
f86rc() { (export HOME="$H_F86"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
           "$BIN_DIR/email-cli-ro" --batch "$@" >/dev/null 2>&1; echo $?); }

# The regression this phase exists for: "show" used to pick one folder
# silently, so the user read a DIFFERENT message than the one searched for.
# With no copy in the configured folder there is nothing to fall back on.
OUT86_1=$(f86 show 837)
check     "86.1 ambiguous show reports the conflict"  "exists in"   "$OUT86_1"
check     "86.2 ambiguity names the vasarlas copy"    "vasarlas"    "$OUT86_1"
check     "86.3 ambiguity names the inbox copy"       "INBOX"       "$OUT86_1"
check_not "86.4 ambiguous show prints no message"     "InboxCopy"   "$OUT86_1"
check     "86.5 ambiguous show fails loudly"          "1"           "$(f86rc show 837)"

# RFC 3501: "Inbox" and "INBOX" are one mailbox, so they must not be counted
# as two conflicting locations.
check_not "86.6 Inbox/INBOX counted once"             "4 folders"   "$OUT86_1"

# With --folder the right message comes back, and File: points at it.
OUT86_2=$(f86 show 837 --folder vasarlas)
check     "86.7 disambiguated show reads the right mail" "OrderCopy" "$OUT86_2"
check_not "86.8 disambiguated show is not the inbox one" "InboxCopy" "$OUT86_2"
check     "86.9 File: names the folder actually used"    "vasarlas"  "$OUT86_2"

# An unambiguous UID still needs no --folder at all.
OUT86_3=$(f86 show 839)
check     "86.10 unique UID still resolves itself"    "TrashOnly"   "$OUT86_3"

# --folder __all__ must not silently fall back to one folder either.
check     "86.11 __all__ show reports the conflict"   "exists in"   "$(f86 show 837 --folder __all__)"

# The workflow fix: cross-folder listings name the folder of every row, so the
# user can pass it straight back to "show".
OUT86_4=$(f86 list --folder "__search__:0:Copy")
check     "86.12 search table has a Folder column"    "Folder"      "$OUT86_4"
check     "86.13 search row names vasarlas"           "vasarlas"    "$OUT86_4"
OUT86_5=$(f86 list --all --folder "__all__")
check     "86.14 __all__ table has a Folder column"   "Folder"      "$OUT86_5"
# A plain single-folder listing has nothing to disambiguate — no extra column.
check_not "86.15 plain listing has no Folder column"  "Folder"      "$(f86 list --all --folder vasarlas)"

# When the configured folder does hold a copy it wins — an unqualified UID is
# read in the user's own mailbox context — but the other copies are still named
# on stderr, and stdout stays clean for scripts.
sed -i 's/^EMAIL_FOLDER=Archive$/EMAIL_FOLDER=INBOX/' \
    "$H_F86/.config/email-cli/accounts/f86@test.local/config.ini"
OUT86_6=$(f86 show 837)
check     "86.16 configured folder wins over ambiguity" "InboxCopy" "$OUT86_6"
check     "86.17 the other copies are still reported"   "vasarlas"  "$OUT86_6"
check     "86.18 it warns rather than fails"            "Warning"   "$OUT86_6"
check     "86.19 preferred show succeeds"               "0"         "$(f86rc show 837)"
# stdout alone (stderr dropped) must carry the message and no diagnostics.
OUT86_7=$( (export HOME="$H_F86"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
            "$BIN_DIR/email-cli-ro" --batch show 837 2>/dev/null || true) )
check     "86.20 stdout holds the message"              "InboxCopy" "$OUT86_7"
check_not "86.21 stdout free of the warning"            "Warning"   "$OUT86_7"

export HOME="$H_ALPHA"

fi

if phase_wanted 87; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 87 — Gmail with a cron sync: the cache must actually be readable
# ════════════════════════════════════════════════════════════════════════════
# A Gmail account with SYNC_INTERVAL > 0 used to fall into the IMAP
# cache-only branch, which reads manifests/<folder>.tsv — a file gmail_sync
# never writes.  Result: "No cached data" over a fully synced store, "Could
# not load message" for messages sitting on disk, and a search that found
# nothing.  Everything here is driven through a real sync of the mock API.
echo ""
echo "--- Phase 87: Gmail cron-mode cache (list, show, search) ---"

alloc_port GMAIL_PORT_C
echo "Starting mock Gmail API server C (port $GMAIL_PORT_C, 30 messages)..."
(MOCK_GMAIL_PORT=$GMAIL_PORT_C MOCK_GMAIL_COUNT=30 \
    MOCK_GMAIL_EMAIL="cron@gmail.com" \
    MOCK_GMAIL_SUBJECT_PREFIX="CronMail-" \
    "$MOCK_GMAIL_BIN") >"$WORK_DIR/mock_gmail_cron.log" 2>&1 &
GMAIL_SERVER_C_PID=$!
sleep 0.5

H_F87="./build/tests/functional/work-$$/homes/f87"
rm -rf "./build/tests/functional/work-$$/homes/f87"
mkdir -p "$H_F87/config/email-cli/accounts/cron@gmail.com" "$H_F87/data"
# SYNC_INTERVAL=5 is the whole point: a background syncer owns the network.
cat > "$H_F87/config/email-cli/accounts/cron@gmail.com/config.ini" <<GCFG87
EMAIL_HOST=
EMAIL_USER=cron@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=fakefaketoken
SYNC_INTERVAL=5
GCFG87

f87env() {
    export XDG_CONFIG_HOME="$H_F87/config"
    export XDG_DATA_HOME="$H_F87/data"
    export XDG_CACHE_HOME="$H_F87/cache"
    export HOME="$H_F87"
    export GMAIL_TEST_TOKEN=testtoken
    export GMAIL_API_BASE_URL="http://localhost:$GMAIL_PORT_C/gmail/v1/users/me"
}
f87() { (f87env; "$BIN_DIR/email-cli-ro" --batch "$@" 2>&1 || true); }
f87out() { (f87env; "$BIN_DIR/email-cli-ro" --batch "$@" 2>/dev/null || true); }
f87rc() { (f87env; "$BIN_DIR/email-cli-ro" --batch "$@" >/dev/null 2>&1; echo $?); }

OUT87_SYNC=$( (f87env; "$BIN_DIR/email-sync" --account cron@gmail.com 2>&1 || true) )
check "87.1 gmail sync completes"                "30 of 30 downloaded" "$OUT87_SYNC"
check "87.2 sync builds label indexes"           "Label indexes rebuilt" "$OUT87_SYNC"

# The syncer writes label indexes and headers, never a manifest — the premise
# the listing code has to respect.
D87="$H_F87/data/email-cli/accounts/cron@gmail.com"
check     "87.3 label index written"             "INBOX.idx" "$(ls "$D87/labels" 2>&1)"
check_not "87.4 no manifest is written by sync"  "tsv"       "$(ls "$D87/manifests" 2>&1)"

# The reported defect: listing a synced Gmail account in cron mode.
OUT87_LIST=$(f87 list --folder INBOX)
check     "87.5 cron-mode list shows the mail"   "CronMail-"   "$OUT87_LIST"
check     "87.6 cron-mode list counts them all"  "of 30 message" "$OUT87_LIST"
check_not "87.7 no bogus empty-cache claim"      "No cached data" "$OUT87_LIST"

# The same store through a real Gmail label.
check "87.8 label listing works too"             "of 30 message" "$(f87 list --folder UNREAD)"

# Opening a message: the .eml is in the flat Gmail store, so cron mode must
# find it locally instead of refusing to connect.
U87=$(head -c 16 "$D87/labels/INBOX.idx")
OUT87_SHOW=$(f87 show "$U87" --folder INBOX)
check     "87.9 cron-mode show reads the mail"   "CronMail-"   "$OUT87_SHOW"
check_not "87.10 show does not fail to load"     "Could not load" "$OUT87_SHOW"
check     "87.11 show succeeds"                  "0"           "$(f87rc show "$U87" --folder INBOX)"
# A bare UID must work as well: Gmail stores one copy, so there is nothing to
# disambiguate.
check     "87.12 bare UID resolves on Gmail"     "CronMail-"   "$(f87 show "$U87")"

# Search across the Gmail cache — it reads .hdr records, not manifests.
# The query string itself is echoed in the "Search: ..." heading, so every
# assertion here matches on the result rows, never on the term searched for.
OUT87_S1=$(f87 list --folder '__search__:0:Message 7')
check "87.13 subject search finds exactly one"   "1-1 of 1 message" "$OUT87_S1"
check "87.14 from search finds all senders"      "1-30 of 30 message" "$(f87 list --folder '__search__:1:sender')"
check "87.15 body search reads the .eml"         "1-30 of 30 message" "$(f87 list --folder '__search__:3:CronMail-body')"
check "87.16 search names the label"             "INBOX"       "$OUT87_S1"
check "87.17 no false positives"                 "No messages" "$(f87 list --folder '__search__:0:ZZNOSUCHMAIL')"

# A label that was never synced still earns the sync advice, not a bare
# "no messages" that would suggest an empty mailbox.
check "87.18 unknown label advises a sync"       "No cached data" "$(f87 list --folder NoSuchLabel)"

# IMAP-only virtual views do not exist on Gmail; say so instead of implying
# the cache is stale.
OUT87_V=$(f87 list --folder __unread__)
check     "87.19 virtual view explained on Gmail" "IMAP-only view" "$OUT87_V"
check     "87.20 it points at the real label"     "UNREAD"         "$OUT87_V"
# The notice is on stderr (87.19 saw it with both streams merged), so stdout is
# empty: said as such, not as an absence that an empty capture would also satisfy.
check_empty "87.21 stdout stays clean for scripts"            "$(f87out list --folder __unread__)"
check       "87.21b and the command itself succeeds"  "^0$"    "$(f87rc list --folder __unread__)"

# No "wait" here: under "set -e" the 143 from a killed child would abort the
# script before the results summary ever printed.
kill "$GMAIL_SERVER_C_PID" || echo "  (mock Gmail C had already exited)"

export HOME="$H_ALPHA"

fi

if phase_wanted 88; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 88 — the credential field says what it did (EMAIL-9, EMAIL-5)
# ════════════════════════════════════════════════════════════════════════════
# The password prompt used to be silent in both directions: nothing was
# echoed while typing, and nothing was said afterwards.  A user could not
# tell a stored password from a dropped one.  The masked echo needs a
# terminal (see the PTY suite); the spoken part is checked here, where stdin
# is a pipe and the prompt reads the line as-is.
echo ""
echo "--- Phase 88: credential field feedback ---"

H_F88="./build/tests/functional/work-$$/homes/f88-$$"
case "$H_F88" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F88 path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f88-$$"
mkdir -p "$H_F88/.config/email-cli/accounts/f88@test.local"
cat > "$H_F88/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
cat > "$H_F88/.config/email-cli/accounts/f88@test.local/config.ini" <<CONFIG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=f88@test.local
EMAIL_PASS=oldpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CONFIG

# Feed the given lines to a config subcommand and append the exit code to the
# captured output.  The status is kept rather than swallowed with "|| true":
# a cancelled wizard exits non-zero on purpose, and that is worth asserting.
f88() {
    local sub="$1" lines="$2"
    (export HOME="$H_F88"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     printf '%b' "$lines" | "$BIN_DIR/email-cli" config "$sub" 2>&1
     echo "exit-code=$?")
}

# A new password reports that it was taken, and how long it was.
OUT88_SET=$(f88 imap '\n\nfreshpass\n\n')
check "88.1 new password acknowledged"  "password updated (9 characters)" "$OUT88_SET"
check "88.2 the change was saved"       "IMAP configuration saved"        "$OUT88_SET"
check "88.3 stored verbatim"            "EMAIL_PASS=freshpass" \
      "$(cat "$H_F88/.config/email-cli/accounts/f88@test.local/config.ini")"

# An empty field keeps the stored password and says so, instead of leaving the
# user to guess which of the two happened.
OUT88_KEEP=$(f88 imap '\n\n\n\n')
check "88.4 empty field says unchanged" "password unchanged"              "$OUT88_KEEP"
check "88.5 the password survived it"   "EMAIL_PASS=freshpass" \
      "$(cat "$H_F88/.config/email-cli/accounts/f88@test.local/config.ini")"

# EOF in the middle of the wizard is a cancel: nothing is written, and the
# user is told so rather than being sent to the log file.
OUT88_EOF=$(f88 imap '\n\n')
check     "88.6 EOF cancels the wizard"   "Cancelled"                "$OUT88_EOF"
check_not "88.7 no misleading log hint"   "Check logs"               "$OUT88_EOF"
check     "88.8 nothing was saved"        "EMAIL_PASS=freshpass" \
      "$(cat "$H_F88/.config/email-cli/accounts/f88@test.local/config.ini")"
check_not "88.9 and it did not claim to"  "IMAP configuration saved" "$OUT88_EOF"
check     "88.10 a cancel exits non-zero" "exit-code=1"              "$OUT88_EOF"

# The SMTP password field speaks the same way.
OUT88_SMTP=$(f88 smtp '\n\n\nsmtpsecret\n')
check "88.11 SMTP password acknowledged" "SMTP password updated (10 characters)" "$OUT88_SMTP"
check "88.12 SMTP change saved"          "SMTP configuration saved"              "$OUT88_SMTP"
check "88.13 and it exits zero"          "exit-code=0"                           "$OUT88_SMTP"
OUT88_SMTP2=$(f88 smtp '\n\n\n\n')
check "88.14 SMTP empty says unchanged"  "SMTP password unchanged"               "$OUT88_SMTP2"

fi

if phase_wanted 89; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 89 — changing only the credential, and being told whether it works
# ════════════════════════════════════════════════════════════════════════════
# A password changed at the provider had no repair path: config offered only
# show / imap / smtp, and a Gmail account - whose refresh token Google revokes
# on a password change - had none at all short of deleting the account.
echo ""
echo "--- Phase 89: config password / config reauth ---"

H_F89="./build/tests/functional/work-$$/homes/f89-$$"
case "$H_F89" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F89 path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f89-$$"
mkdir -p "$H_F89/.config/email-cli/accounts/f89@test.local"
cat > "$H_F89/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
# Points at mock server 1, which answers on its port for the whole run.
cat > "$H_F89/.config/email-cli/accounts/f89@test.local/config.ini" <<CONFIG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=f89@test.local
EMAIL_PASS=oldpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CONFIG
F89_INI="$H_F89/.config/email-cli/accounts/f89@test.local/config.ini"

# A Gmail account for the other half.  GMAIL_TEST_NO_CLIENT_ID makes
# gmail_auth behave as a build with no compiled-in credentials, so the
# authorization refuses at once instead of opening a browser and waiting out
# its 300-second timeout.
H_F89G="./build/tests/functional/work-$$/homes/f89g-$$"
case "$H_F89G" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F89G path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f89g-$$"
mkdir -p "$H_F89G/.config/email-cli/accounts/f89@gmail.com"
# Plaintext credentials, so the stored token can be read back as written:
# with obfuscation on, merely loading the config re-encrypts it and the test
# could no longer tell a surviving token from a replaced one.
cat > "$H_F89G/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
cat > "$H_F89G/.config/email-cli/accounts/f89@gmail.com/config.ini" <<'CONFIG'
EMAIL_USER=f89@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=revoked-token
CONFIG

# Run a config subcommand with the exit code appended, so a non-zero status is
# asserted rather than swallowed.
f89() {
    local home="$1" sub="$2" lines="$3"
    (export HOME="$home"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     export GMAIL_TEST_NO_CLIENT_ID=1
     printf '%b' "$lines" | "$BIN_DIR/email-cli" config "$sub" 2>&1
     echo "exit-code=$?")
}

# The two subcommands must be discoverable, or they are no repair path at all.
OUT89_HELP=$( (export HOME="$H_F89"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-cli" config --help 2>&1; echo "exit-code=$?") )
check "89.1 help lists 'password'"  "password  Change nothing but the password" "$OUT89_HELP"
check "89.2 help lists 'reauth'"    "reauth    Renew a Gmail account"           "$OUT89_HELP"

# A new password: taken, saved, and then actually tried against the server.
OUT89_SET=$(f89 "$H_F89" password 'freshpw89\n')
check "89.3 password acknowledged"   "password updated (9 characters)" "$OUT89_SET"
check "89.4 password saved"          "Password saved"                  "$OUT89_SET"
check "89.5 the connection is tried" "Checking the connection to imaps://localhost:$IMAP1_PORT" "$OUT89_SET"
check "89.6 and the server took it"  "Connected: f89@test.local"       "$OUT89_SET"
check "89.7 exits zero"              "exit-code=0"                     "$OUT89_SET"
check "89.8 stored verbatim"         "EMAIL_PASS=freshpw89"            "$(cat "$F89_INI")"
# Nothing but the password may move: that is the point of the subcommand.
check "89.9 host untouched"          "EMAIL_HOST=imaps://localhost:$IMAP1_PORT" "$(cat "$F89_INI")"
check "89.10 folder untouched"       "EMAIL_FOLDER=INBOX"                "$(cat "$F89_INI")"

# An empty field keeps the stored password - and still answers the other half
# of the question: does the one I have still work?
OUT89_KEEP=$(f89 "$H_F89" password '\n')
check "89.11 empty says unchanged"   "password unchanged"              "$OUT89_KEEP"
check "89.12 still tests it"         "Connected: f89@test.local"       "$OUT89_KEEP"
check "89.13 and exits zero"         "exit-code=0"                     "$OUT89_KEEP"
check "89.14 password still there"   "EMAIL_PASS=freshpw89"            "$(cat "$F89_INI")"

# EOF is a cancel: nothing written, and said so without a log-file pointer.
OUT89_EOF=$(f89 "$H_F89" password '')
check     "89.15 EOF cancels"          "Cancelled"            "$OUT89_EOF"
check_not "89.16 no log-file pointer"  "Check logs"           "$OUT89_EOF"
check     "89.17 exits non-zero"       "exit-code=1"          "$OUT89_EOF"
check     "89.18 nothing was written"  "EMAIL_PASS=freshpw89" "$(cat "$F89_INI")"

# A server that is not there is reported as such, not as success.
H_F89D="./build/tests/functional/work-$$/homes/f89d-$$"
case "$H_F89D" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F89D path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f89d-$$"
mkdir -p "$H_F89D/.config/email-cli/accounts/f89d@test.local"
cat > "$H_F89D/.config/email-cli/accounts/f89d@test.local/config.ini" <<'CONFIG'
EMAIL_HOST=imaps://localhost:9099
EMAIL_USER=f89d@test.local
EMAIL_PASS=oldpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CONFIG
OUT89_DEAD=$(f89 "$H_F89D" password 'whatever\n')
check "89.19 a dead server is reported" "did not accept the connection" "$OUT89_DEAD"
check "89.20 and the command fails"     "exit-code=1"                   "$OUT89_DEAD"

# 'config reauth' on an IMAP account refuses and names the right subcommand.
OUT89_RA_IMAP=$(f89 "$H_F89" reauth '')
check "89.21 reauth refused on IMAP"   "no authorization to renew"  "$OUT89_RA_IMAP"
check "89.22 and it names 'password'"  "config password"            "$OUT89_RA_IMAP"
check "89.23 exits non-zero"           "exit-code=1"                "$OUT89_RA_IMAP"

# 'config password' on a Gmail account explains why there is no password and
# carries out the renewal the user actually needs.
OUT89_PW_GMAIL=$(f89 "$H_F89G" password '')
check "89.24 Gmail has no password here" "it has no password here"   "$OUT89_PW_GMAIL"
check "89.25 and says what revoked it"   "revokes"                   "$OUT89_PW_GMAIL"
check "89.26 it hands over to reauth"    "config reauth"             "$OUT89_PW_GMAIL"
check "89.27 a failed renewal is said"   "was not completed"         "$OUT89_PW_GMAIL"
check "89.28 and the command fails"      "exit-code=1"               "$OUT89_PW_GMAIL"
# The revoked token must still be there: a failed renewal may not destroy it.
check "89.29 the old token survives"     "GMAIL_REFRESH_TOKEN=revoked-token" \
      "$(cat "$H_F89G/.config/email-cli/accounts/f89@gmail.com/config.ini")"

# 'config reauth' on a Gmail account reaches the authorization flow itself.
OUT89_RA_GMAIL=$(f89 "$H_F89G" reauth '')
check "89.30 reauth runs on Gmail"   "OAuth2 credentials are not configured" "$OUT89_RA_GMAIL"
check "89.31 and reports the failure" "was not completed"                    "$OUT89_RA_GMAIL"

fi

if phase_wanted 90; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 90 — config tells the truth about the account type (EMAIL-8)
# ════════════════════════════════════════════════════════════════════════════
# 'config show' printed an IMAP host/user/password block for a Gmail account
# too, and 'config imap' then ran on it: it accepted a new password, wrote
# EMAIL_HOST/EMAIL_PASS into the config and said "IMAP configuration saved",
# while GMAIL_MODE=1 stayed and sync kept using the API.
echo ""
echo "--- Phase 90: config is account-type aware ---"

H_F90G="./build/tests/functional/work-$$/homes/f90g-$$"
case "$H_F90G" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F90G path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f90g-$$"
mkdir -p "$H_F90G/.config/email-cli/accounts/f90@gmail.com"
cat > "$H_F90G/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
cat > "$H_F90G/.config/email-cli/accounts/f90@gmail.com/config.ini" <<'CONFIG'
EMAIL_USER=f90@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=f90-token
EMAIL_FOLDER=INBOX
CONFIG
F90G_INI="$H_F90G/.config/email-cli/accounts/f90@gmail.com/config.ini"

f90() {
    local home="$1" sub="$2" lines="$3"
    (export HOME="$home"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     export GMAIL_TEST_NO_CLIENT_ID=1
     printf '%b' "$lines" | "$BIN_DIR/email-cli" config "$sub" 2>&1
     echo "exit-code=$?")
}

# 'config show' on a Gmail account names the type and the credential that
# actually grants access — and shows no IMAP password at all.
OUT90_SHOW=$(f90 "$H_F90G" show '')
check     "90.1 Gmail type named"          "Account type: Gmail"        "$OUT90_SHOW"
check     "90.2 says it has no password"   "none — Gmail accounts do not use one" "$OUT90_SHOW"
check     "90.3 authorization shown"       "Authorization: stored"      "$OUT90_SHOW"
check     "90.4 names the renewal command" "config reauth"              "$OUT90_SHOW"
check_not "90.5 no IMAP block"             "IMAP:"                      "$OUT90_SHOW"
check_not "90.6 no masked password line"   "Password: \*\*\*\*"         "$OUT90_SHOW"
check     "90.7 exits zero"                "exit-code=0"                "$OUT90_SHOW"

# A missing token is reported as missing, not as present.
H_F90N="./build/tests/functional/work-$$/homes/f90n-$$"
case "$H_F90N" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F90N path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f90n-$$"
mkdir -p "$H_F90N/.config/email-cli/accounts/f90n@gmail.com"
# The key must be present for the loader to accept gmail_mode at all; an
# empty value is an account that was never authorized, or whose token was
# cleared.  That must read as missing, with the way out named.
cat > "$H_F90N/.config/email-cli/accounts/f90n@gmail.com/config.ini" <<'CONFIG'
EMAIL_USER=f90n@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=
CONFIG
OUT90_TOK=$(f90 "$H_F90N" show '')
check "90.8 a missing token reads as missing" "Authorization: missing" "$OUT90_TOK"
check "90.9 and names the way out"            "config reauth"          "$OUT90_TOK"

# 'config imap' on a Gmail account refuses, and writes nothing.
OUT90_IMAP=$(f90 "$H_F90G" imap 'imaps://imap.example.com\n\nnewpass\n\n')
check     "90.10 refused on a Gmail account"  "does not use IMAP"          "$OUT90_IMAP"
check     "90.11 and names reauth"           "config reauth"              "$OUT90_IMAP"
check     "90.12 exits non-zero"             "exit-code=1"                "$OUT90_IMAP"
check_not "90.13 it does not claim success"  "IMAP configuration saved"   "$OUT90_IMAP"
check_not "90.14 no EMAIL_HOST was written"  "EMAIL_HOST=imaps://imap.example.com" "$(cat "$F90G_INI")"
check_not "90.15 no password was written"    "EMAIL_PASS=newpass"         "$(cat "$F90G_INI")"
check     "90.16 the token is untouched"     "GMAIL_REFRESH_TOKEN=f90-token" "$(cat "$F90G_INI")"

# 'config smtp' likewise: Gmail sends through the API.
OUT90_SMTP=$(f90 "$H_F90G" smtp '\n\n\n\n')
check     "90.17 smtp refused on Gmail"      "not SMTP"                   "$OUT90_SMTP"
check     "90.18 exits non-zero"             "exit-code=1"                "$OUT90_SMTP"
check_not "90.19 it does not claim success"  "SMTP configuration saved"   "$OUT90_SMTP"
check_not "90.20 no SMTP_HOST was written"   "SMTP_HOST"                  "$(cat "$F90G_INI")"

# An IMAP account may not be pointed at Gmail through the sub-wizard either:
# the first-run wizard has always refused that host.
H_F90I="./build/tests/functional/work-$$/homes/f90i-$$"
case "$H_F90I" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F90I path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f90i-$$"
mkdir -p "$H_F90I/.config/email-cli/accounts/f90@test.local"
cat > "$H_F90I/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
cat > "$H_F90I/.config/email-cli/accounts/f90@test.local/config.ini" <<CONFIG
EMAIL_HOST=imaps://localhost:$IMAP1_PORT
EMAIL_USER=f90@test.local
EMAIL_PASS=testpass
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CONFIG
F90I_INI="$H_F90I/.config/email-cli/accounts/f90@test.local/config.ini"

OUT90_GH=$(f90 "$H_F90I" imap 'imap.gmail.com\n\n\n\n\n')
check     "90.21 gmail host refused"        "not reachable over IMAP"   "$OUT90_GH"
check     "90.22 it names the account type" "\[2\] Gmail"               "$OUT90_GH"
check_not "90.23 and it was not stored"     "EMAIL_HOST=imaps://imap.gmail.com" "$(cat "$F90I_INI")"
# The prompt is repeated rather than the wizard abandoned, so the next answer
# is still accepted.
check     "90.24 the host prompt repeats"   "EMAIL_HOST=imaps://localhost" "$(cat "$F90I_INI")"

fi

if phase_wanted 91; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 91 — a rejected credential says so, and says what to do (EMAIL-10)
# ════════════════════════════════════════════════════════════════════════════
# The rejection used to arrive as "ERROR: LOGIN failed for user X on Y": a log
# line with no cause, no cure, and nothing of what the server itself said.
# The mock IMAP server now enforces a password when MOCK_IMAP_PASSWORD is set,
# so the product's own handling of a refusal is finally observable.
echo ""
echo "--- Phase 91: a rejected login is explained ---"

alloc_port AUTH_PORT
echo "Starting mock IMAP server with password enforcement (port $AUTH_PORT)..."
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$AUTH_PORT MOCK_IMAP_PASSWORD="rightpass91" \
    MOCK_IMAP_SUBJECT="AuthMsg" "$MOCK_SERVER_BIN") \
    >"$WORK_DIR/mock_auth.log" 2>&1 &
AUTH_SERVER_PID=$!
sleep 0.5

H_F91="./build/tests/functional/work-$$/homes/f91-$$"
case "$H_F91" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_F91 path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/f91-$$"
mkdir -p "$H_F91/.config/email-cli/accounts/f91@test.local"
cat > "$H_F91/.config/email-cli/settings.ini" <<'SETTINGS'
credential_obfuscation=false
SETTINGS
cat > "$H_F91/.config/email-cli/accounts/f91@test.local/config.ini" <<CONFIG
EMAIL_HOST=imaps://localhost:$AUTH_PORT
EMAIL_USER=f91@test.local
EMAIL_PASS=stale-password
EMAIL_FOLDER=INBOX
SSL_NO_VERIFY=1
CONFIG

f91() {
    local sub="$1" lines="$2"
    (export HOME="$H_F91"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
     printf '%b' "$lines" | "$BIN_DIR/email-cli" config "$sub" 2>&1
     echo "exit-code=$?")
}

# A wrong password: the refusal is named as a refusal, the server's own words
# are passed on, and the command that repairs it is named.
OUT91_BAD=$(f91 password 'wrongpass91\n')
check "91.1 named as a rejection"      "rejected the login for f91@test.local" "$OUT91_BAD"
check "91.2 the server's words quoted" "AUTHENTICATIONFAILED"                  "$OUT91_BAD"
check "91.3 says what is wrong"        "username or password is not accepted"  "$OUT91_BAD"
check "91.4 names the repair command"  "config password"                       "$OUT91_BAD"
check "91.5 and the command fails"     "exit-code=1"                           "$OUT91_BAD"

# The right password is accepted, and says so — the same check that condemns a
# wrong one must clear a right one, or it proves nothing.
OUT91_GOOD=$(f91 password 'rightpass91\n')
check     "91.6 the right one connects"  "Connected: f91@test.local" "$OUT91_GOOD"
check     "91.7 exits zero"              "exit-code=0"               "$OUT91_GOOD"
check_not "91.8 and nothing is rejected" "rejected the login"        "$OUT91_GOOD"

# email-sync hits the same path: a stale password must not come out as a
# generic "could not retrieve folder list" with no cause given.
sed -i 's/^EMAIL_PASS=.*/EMAIL_PASS=stale-again/' \
    "$H_F91/.config/email-cli/accounts/f91@test.local/config.ini"
OUT91_SYNC=$( (export HOME="$H_F91"; unset XDG_DATA_HOME XDG_CONFIG_HOME XDG_CACHE_HOME
    "$BIN_DIR/email-sync" 2>&1; echo "exit-code=$?") )
check "91.9 sync names the rejection"  "rejected the login" "$OUT91_SYNC"
check "91.10 sync names the repair"    "config password"    "$OUT91_SYNC"
check "91.11 sync fails"               "exit-code=1"        "$OUT91_SYNC"

kill "$AUTH_SERVER_PID" || echo "  (the password-enforcing mock had already exited)"

fi

if phase_wanted 92; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 92: the Claude skill (policies/cli-skill-model.md) agrees with the binary
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "=== Phase 92: claude/skills/email-cli/SKILL.md ==="
SKILL92="$PROJECT_ROOT/claude/skills/email-cli/SKILL.md"
SKILL92_TEXT=$(cat "$SKILL92"); SKILL92_RC=$?
check "92.1 the skill file is readable and has content" "email-cli" "$SKILL92_TEXT"
check "92.1b read exit status is zero" "^0$" "$SKILL92_RC"
check "92.2 front matter opens the file" "^---$" "$(echo "$SKILL92_TEXT" | head -1)"
check "92.3 name is the CLI's name" "^name: email-cli$" "$(echo "$SKILL92_TEXT" | sed -n 2p)"
check "92.4 description says when to use" "^description: Use when " "$(echo "$SKILL92_TEXT" | sed -n 3p)"
check "92.5 description says when not to" "Do not use for" "$(echo "$SKILL92_TEXT" | sed -n 3p)"
check "92.6 the read-only variant is named" "email-cli-ro" "$SKILL92_TEXT"

# Every command the binary advertises is in the skill ...
HELP92=$("$BIN_DIR/email-cli" --help 2>&1)
CMDS92=$(echo "$HELP92" | sed -n '/^Reading:/,/^Help:/p' \
         | grep -E '^  [a-z][a-z-]+ ' | awk '{print $1}' | sort -u)
check "92.7 the help lists commands to compare" "^list$" "$CMDS92"
for c in $CMDS92; do
    case "$c" in add-account|remove-account|config|migrate-credentials|help) continue ;; esac
    check "92.8 skill mentions '$c'" "$c" "$SKILL92_TEXT"
done
# ... and every read-only command the skill lists is accepted by email-cli-ro.
RO92=$("$BIN_DIR/email-cli-ro" --help 2>&1)
for c in list show list-folders list-labels list-attachments save-attachment list-accounts; do
    check "92.9 email-cli-ro has '$c'" "^  $c" "$RO92"
done
# email-cli-ro has no write command: its help is non-empty and lists no send.
SEND92=$(echo "$RO92" | awk '/^  send /{n++} END{print n+0}')
check "92.10 email-cli-ro help is non-empty" "Reading:" "$RO92"
check "92.11 email-cli-ro lists no send" "^0$" "$SEND92"

fi

if phase_wanted 93; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 93: the licence is GPL-3.0-only everywhere it is stated (EMAIL-30)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "=== Phase 93: GPL-3.0-only, never 'or later' ==="
TRACKED93=$(git -C "$PROJECT_ROOT" ls-files)
check "93.1 the file list is not empty" "^LICENSE$" "$TRACKED93"
# Every tracked text file except the licence text itself (whose standard
# paragraphs discuss later versions) and the submodules.
OR_LATER93=$(cd "$PROJECT_ROOT" && echo "$TRACKED93" | grep -v -e '^LICENSE$' -e '^deps/' -e '^tests/functional/run_functional.sh$' \
    | xargs grep -n -I -i -E 'GPL-3\.0-or-later|GPL-3\.0\+|or \(at your option\) any later|GPLv3\+|or later' \
    | awk 'END{print NR}')
check "93.2 nothing says 'or later'" "^0$" "$OR_LATER93"
check "93.3 CMakeLists SPDX tag"  "^# SPDX-License-Identifier: GPL-3.0-only$" \
      "$(head -1 "$PROJECT_ROOT/CMakeLists.txt")"
check "93.4 package licence field" 'CPACK_RPM_PACKAGE_LICENSE *"GPL-3.0-only"' \
      "$(cat "$PROJECT_ROOT/CMakeLists.txt")"
check "93.5 README names the licence" "GPL-3.0-only" "$(cat "$PROJECT_ROOT/README.md")"

fi

if phase_wanted 94; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 94: a client that disconnects mid-response must not kill the mocks
# (EMAIL-42: SIGPIPE ended the IMAP mock, and every later test timed out)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "=== Phase 94: the IMAP mock survives clients that vanish mid-response ==="
alloc_port P94
LOG94="$PROJECT_ROOT/build/tests/functional/work-$$/mock_sigpipe.log"
(cd "$PROJECT_ROOT/build" && MOCK_IMAP_PORT=$P94 MOCK_IMAP_COUNT=250 \
    "$MOCK_SERVER_BIN") >"$LOG94" 2>&1 &
PID94=$!
sleep 1
kill -0 "$PID94" && ALIVE94=yes || ALIVE94=no
check "94.1 the mock started" "^yes$" "$ALIVE94"
# Fifteen clients log in, ask for a large response and are cut off by timeout
# before it has been read.  Their PIDs are collected one by one: `jobs -p`
# would also list the long-running mocks of this script and wait forever.
CLIENTS94=""
for i in $(seq 1 15); do
    printf 'a1 LOGIN u p\r\na2 SELECT INBOX\r\na3 FETCH 1:* (FLAGS)\r\na4 FETCH 1:* (BODY[HEADER])\r\n' \
        | timeout 3 openssl s_client -quiet -connect 127.0.0.1:$P94 >>"$LOG94.clients" 2>&1 &
    CLIENTS94="$CLIENTS94 $!"
done
for c in $CLIENTS94; do
    # Status 124 (timeout) is the expected end of such a client.
    wait "$c" && W94=0 || W94=$?
done
sleep 1
kill -0 "$PID94" && ALIVE94=yes || ALIVE94=no
check "94.2 the mock is still running" "^yes$" "$ALIVE94"
# s_client may be ended by the timeout (status 124); the greeting is what counts.
GREET94=$( (printf 'a1 LOGOUT\r\n' | timeout 5 openssl s_client -quiet -connect 127.0.0.1:$P94) 2>&1 ) \
    && G94=0 || G94=$?
check "94.3 and still answers a new client" "OK" "$GREET94"
kill "$PID94"

fi

if phase_wanted 95; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 95: the suite leaves no mock server behind (EMAIL-42)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "=== Phase 95: no mock server outlives the run ==="
cleanup_mocks
sleep 1
LISTEN95=$(ss -ltn)
check "95.1 the listener list is readable" "^State" "$LISTEN95"
for p95 in $IMAP1_PORT $IMAP2_PORT $IMAP3_PORT $IMAP200_PORT $IMAP250_PORT; do
    check_not "95.2 port $p95 is free" ":$p95 " "$LISTEN95"
done

fi

if phase_wanted 97; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 97: two mocks cannot share a port, and they listen on loopback only
# (EMAIL-14: SO_REUSEPORT let a stale mock split connections with a new one)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "=== Phase 97: mock servers refuse a port that is taken ==="
alloc_port P97
for kind97 in gmail smtp; do
    if [ "$kind97" = gmail ]; then
        BIN97="$MOCK_GMAIL_BIN"; ENV97="MOCK_GMAIL_PORT=$P97"
    else
        BIN97="$MOCK_SMTP_BIN";  ENV97="MOCK_SMTP_PORT=$P97"
    fi
    LOG97="$PROJECT_ROOT/build/tests/functional/work-$$/mock_port97_$kind97"
    (cd "$PROJECT_ROOT/build" && env "$ENV97" "$BIN97") >"$LOG97.a.log" 2>&1 &
    A97=$!
    sleep 1
    kill -0 "$A97" && A97UP=yes || A97UP=no
    check "97.1 first $kind97 mock is up" "^yes$" "$A97UP"
    check "97.2 $kind97 mock listens on loopback only" "127.0.0.1:$P97 " "$(ss -ltn)"
    check_not "97.3 $kind97 mock is not on all interfaces" "0.0.0.0:$P97 " "$(ss -ltn)"
    # In the foreground under a timeout: a mock that binds anyway runs until
    # the timeout kills it (status 124); one that refuses exits by itself.
    (cd "$PROJECT_ROOT/build" && env "$ENV97" timeout 3 "$BIN97") >"$LOG97.b.log" 2>&1 \
        && B97RC=0 || B97RC=$?
    check "97.4 second $kind97 mock on the same port exits by itself" "^[1-9][0-9]*$" "$B97RC"
    check_not "97.5 it was not left running until the timeout" "^124$" "$B97RC"
    check "97.6 saying why" "Address already in use" "$(cat "$LOG97.b.log")"
    kill -0 "$A97" && A97UP=yes || A97UP=no
    check "97.7 the first mock is undisturbed" "^yes$" "$A97UP"
    kill "$A97"
    wait "$A97" && A97RC=0 || A97RC=$?    # SIGTERM status: not a verdict
done

fi

if phase_wanted 98; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 98 — Gmail mail rules reach Google (EMAIL-20)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 98: Gmail rules push labels to the server (EMAIL-20) ---"

alloc_port GR98_PORT
GR98_LOG="$PROJECT_ROOT/build/tests/functional/work-$$/mock_gmail_rules98.log"
(MOCK_GMAIL_PORT=$GR98_PORT MOCK_GMAIL_COUNT=3 \
    MOCK_GMAIL_EMAIL="grules98@gmail.com" \
    "$MOCK_GMAIL_BIN") >"$GR98_LOG" 2>&1 &
GR98_PID=$!

H_GR98="./build/tests/functional/work-$$/homes/grules98-$$"
ACCT_GR98="grules98@gmail.com"
mkdir -p "$H_GR98/config/email-cli/accounts/$ACCT_GR98"
mkdir -p "$H_GR98/data"
cat > "$H_GR98/config/email-cli/accounts/$ACCT_GR98/config.ini" <<'GCFG97'
EMAIL_HOST=
EMAIL_USER=grules98@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=faketoken98
GCFG97

run_gr98_sync() {
    (export XDG_CONFIG_HOME="$H_GR98/config"
     export XDG_DATA_HOME="$H_GR98/data"
     export XDG_CACHE_HOME="$H_GR98/cache"
     export HOME="$H_GR98"
     export GMAIL_TEST_TOKEN=testtoken98
     export GMAIL_API_BASE_URL="http://localhost:$GR98_PORT/gmail/v1/users/me"
     "$BIN_DIR/email-sync" "$@" 2>&1 && echo "exit-code=0" || echo "exit-code=$?")
}

count_gr98() { awk -v pat="$1" '$0 ~ pat { n++ } END { print n + 0 }' "$GR98_LOG"; }

sleep 0.5
GR98_FIRST=$( run_gr98_sync )
check "98.0 first Gmail sync succeeds" "exit-code=0" "$GR98_FIRST"

cat > "$H_GR98/config/email-cli/accounts/$ACCT_GR98/rules.ini" <<'GRINI97'
[rule "Known label"]
if-from = *sender1@*
then-add-label = Work

[rule "New label"]
if-from = *sender2@*
then-add-label = FreshRuleLabel
GRINI97

# dry-run must not push anything to Google
GR98_DRYOUT=$( (export XDG_CONFIG_HOME="$H_GR98/config"
     export XDG_DATA_HOME="$H_GR98/data"
     export XDG_CACHE_HOME="$H_GR98/cache"
     export HOME="$H_GR98"
     export GMAIL_TEST_TOKEN=testtoken98
     export GMAIL_API_BASE_URL="http://localhost:$GR98_PORT/gmail/v1/users/me"
     "$BIN_DIR/email-cli" rules apply --dry-run 2>&1 && echo "exit-code=0" || echo "exit-code=$?") )
check "98.1 dry-run: exit status 0" "exit-code=0" "$GR98_DRYOUT"
check "98.2 dry-run sends no label change to Google" "^0$" "$(count_gr98 MODIFY)"

# real apply: the local change reaches Google
GR98_OUT=$( run_gr98_sync --apply-rules )
check "98.3 apply-rules: exit status 0" "exit-code=0" "$GR98_OUT"
check_not "98.4 apply-rules: no error" "Error:" "$GR98_OUT"
GR98_MOD=$(awk '/MODIFY/' "$GR98_LOG")
check "98.5 known label: message 1 modified with its label ID" \
    "MODIFY 0000000000000001 .*addLabelIds.*Work" "$GR98_MOD"
check "98.6 missing label is created and its new ID pushed for message 2" \
    "MODIFY 0000000000000002 .*addLabelIds.*Label_Test001" "$GR98_MOD"
check "98.7 the missing label was created exactly once" "^1$" \
    "$(count_gr98 'POST /gmail/v1/users/me/labels')"

# the queue is drained: another sync sends nothing more
GR98_BEFORE=$(count_gr98 MODIFY)
GR98_AGAIN=$( run_gr98_sync )
check "98.8 later sync: exit status 0" "exit-code=0" "$GR98_AGAIN"
check "98.9 a later sync does not resend drained changes" "^$GR98_BEFORE$" \
    "$(count_gr98 MODIFY)"
GR98_QUEUE="$H_GR98/data/email-cli/accounts/$ACCT_GR98/pending_labels.tsv"
if [ -e "$GR98_QUEUE" ]; then
    echo "  [FAIL] 98.10 pending_labels.tsv removed once pushed"
    FAILED=$((FAILED + 1))
else
    echo "  [PASS] 98.10 pending_labels.tsv removed once pushed"
    PASSED=$((PASSED + 1))
fi

kill "$GR98_PID"
case "$H_GR98" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_GR98 path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/${H_GR98##./build/tests/functional/work-$$/homes/}"

fi

if phase_wanted 99; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 99 — Gmail flag changes made offline reach Google on the next sync
#            (EMAIL-21)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 99: Gmail offline flag change is queued and pushed (EMAIL-21) ---"

alloc_port GF99_PORT
alloc_port GF99_DEAD_PORT
GF99_LOG="$PROJECT_ROOT/build/tests/functional/work-$$/mock_gmail_flag99.log"
(MOCK_GMAIL_PORT=$GF99_PORT MOCK_GMAIL_COUNT=3 \
    MOCK_GMAIL_EMAIL="gflag99@gmail.com" \
    "$MOCK_GMAIL_BIN") >"$GF99_LOG" 2>&1 &
GF99_PID=$!

H_GF99="./build/tests/functional/work-$$/homes/gflag99-$$"
ACCT_GF99="gflag99@gmail.com"
mkdir -p "$H_GF99/config/email-cli/accounts/$ACCT_GF99"
mkdir -p "$H_GF99/data"
cat > "$H_GF99/config/email-cli/accounts/$ACCT_GF99/config.ini" <<'GCFG99'
EMAIL_HOST=
EMAIL_USER=gflag99@gmail.com
GMAIL_MODE=1
GMAIL_REFRESH_TOKEN=faketoken99
GCFG99

# run_gf99 PORT BINARY ARGS...: PORT picks the live mock or a closed port
run_gf99() {
    local port="$1" bin="$2"; shift 2
    (export XDG_CONFIG_HOME="$H_GF99/config"
     export XDG_DATA_HOME="$H_GF99/data"
     export XDG_CACHE_HOME="$H_GF99/cache"
     export HOME="$H_GF99"
     export GMAIL_TEST_TOKEN=testtoken99
     export GMAIL_API_BASE_URL="http://localhost:$port/gmail/v1/users/me"
     "$BIN_DIR/$bin" "$@" 2>&1 && echo "exit-code=0" || echo "exit-code=$?")
}

sleep 0.5
GF99_FIRST=$( run_gf99 $GF99_PORT email-sync )
check "99.0 first Gmail sync succeeds" "exit-code=0" "$GF99_FIRST"

GF99_BEFORE=$(awk '/MODIFY/ { n++ } END { print n + 0 }' "$GF99_LOG")
GF99_OFF=$( run_gf99 $GF99_DEAD_PORT email-cli mark-read 0000000000000001 )
check "99.1 offline mark-read promises the next sync" "queued for next sync" "$GF99_OFF"
GF99_QUEUE="$H_GF99/data/email-cli/accounts/$ACCT_GF99/pending_labels.tsv"
check "99.2 the change sits in pending_labels.tsv" "0000000000000001	UNREAD	0" \
    "$(cat "$GF99_QUEUE")"
GF99_DEADQ="$H_GF99/data/email-cli/accounts/$ACCT_GF99/pending_flags"
if [ -e "$GF99_DEADQ" ]; then
    echo "  [FAIL] 99.3 nothing is written to the undrained pending_flags queue"
    FAILED=$((FAILED + 1))
else
    echo "  [PASS] 99.3 nothing is written to the undrained pending_flags queue"
    PASSED=$((PASSED + 1))
fi

GF99_SYNC=$( run_gf99 $GF99_PORT email-sync )
check "99.4 sync after reconnecting succeeds" "exit-code=0" "$GF99_SYNC"
check "99.5 the offline change reached Google" \
    "MODIFY 0000000000000001 .*removeLabelIds.*UNREAD" \
    "$(awk '/MODIFY/' "$GF99_LOG")"
if [ -e "$GF99_QUEUE" ]; then
    echo "  [FAIL] 99.6 pending_labels.tsv removed once pushed"
    FAILED=$((FAILED + 1))
else
    echo "  [PASS] 99.6 pending_labels.tsv removed once pushed"
    PASSED=$((PASSED + 1))
fi

# online: the synchronous push does the work and queues nothing
GF99_ON=$( run_gf99 $GF99_PORT email-cli mark-unread 0000000000000001 )
check "99.7 online mark-unread succeeds" "exit-code=0" "$GF99_ON"
check_not "99.8 online change is not reported as queued" "queued" "$GF99_ON"
if [ -e "$GF99_QUEUE" ]; then
    echo "  [FAIL] 99.9 online change queues nothing"
    FAILED=$((FAILED + 1))
else
    echo "  [PASS] 99.9 online change queues nothing"
    PASSED=$((PASSED + 1))
fi

kill "$GF99_PID"
case "$H_GF99" in ./build/tests/functional/work-$$/homes/*) ;; *) echo "ERROR: unsafe H_GF99 path" >&2; exit 1 ;; esac
rm -rf "./build/tests/functional/work-$$/homes/${H_GF99##./build/tests/functional/work-$$/homes/}"

fi

if phase_wanted 100; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 100 — mocks take a kernel-picked port and say which (EMAIL-33)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 100: mock servers bind an ephemeral loopback port and publish it (EMAIL-33) ---"
for kind100 in imap gmail smtp; do
    case "$kind100" in
        imap)  BIN100="$MOCK_SERVER_BIN"; PFX100=MOCK_IMAP ;;
        gmail) BIN100="$MOCK_GMAIL_BIN";  PFX100=MOCK_GMAIL ;;
        smtp)  BIN100="$MOCK_SMTP_BIN";   PFX100=MOCK_SMTP ;;
    esac
    PF100A="$WORK_DIR/port100-$kind100-a"
    PF100B="$WORK_DIR/port100-$kind100-b"
    # No port variable at all: the mock must not fall back to a fixed number.
    (cd "$PROJECT_ROOT/build" && env -u ${PFX100}_PORT "${PFX100}_PORT_FILE=$PF100A" \
        "$BIN100") >"$WORK_DIR/mock100-$kind100-a.log" 2>&1 &
    PID100A=$!
    (cd "$PROJECT_ROOT/build" && env -u ${PFX100}_PORT "${PFX100}_PORT_FILE=$PF100B" \
        "$BIN100") >"$WORK_DIR/mock100-$kind100-b.log" 2>&1 &
    PID100B=$!
    for _ in $(seq 1 50); do
        [ -s "$PF100A" ] && [ -s "$PF100B" ] && break
        sleep 0.1
    done
    check "100.1 $kind100 mock publishes its port" "^[0-9][0-9]*$" "$(cat "$PF100A" 2>&1)"
    PORT100A=$(cat "$PF100A"); PORT100B=$(cat "$PF100B")
    check_not "100.2 $kind100 mock port is not the old fixed one" "^\(9993\|9025\|9997\)$" "$PORT100A"
    check_not "100.3 two $kind100 mocks got different ports" "^$PORT100A$" "$PORT100B"
    LISTEN100=$(ss -ltn)
    check "100.4 $kind100 mock listens on loopback" "127.0.0.1:$PORT100A " "$LISTEN100"
    check_not "100.5 $kind100 mock is not on all interfaces" "0.0.0.0:$PORT100A " "$LISTEN100"
    kill "$PID100A" "$PID100B"
    wait "$PID100A" && R100=0 || R100=$?     # SIGTERM status: not a verdict
    wait "$PID100B" && R100=0 || R100=$?
done

# No test source names /tmp, and no mock is started on a literal port.  The
# patterns are assembled so that this file does not match itself.
T100="/t""mp"
SRC100=$(grep -rIl -e "$T100" tests/unit tests/pty tests/integration tests/common \
    tests/functional/mock_imap_server.c tests/functional/mock_gmail_api_server.c || true)
check_empty "100.6 no test source uses $T100" "$SRC100"
FIXED100=$(grep -rIn -E 'MOCK_[A-Z]+_PORT=[0-9]+|MOCK_[A-Z]+_PORT", *"[0-9]+' tests || true)
check_empty "100.7 no mock is started on a literal port" "$FIXED100"
fi

if phase_wanted 101; then
# ════════════════════════════════════════════════════════════════════════════
# Phase 101 — CI checks the library submodules out (EMAIL-27)
# ════════════════════════════════════════════════════════════════════════════
echo ""
echo "--- Phase 101: every CI workflow checks out submodules recursively (EMAIL-27) ---"
for wf101 in "$PROJECT_ROOT"/.github/workflows/*.yml; do
    n101=$(basename "$wf101")
    if grep -A2 'actions/checkout@' "$wf101" | grep -q 'submodules: recursive'; then
        check "101.1 $n101: checkout fetches submodules recursively" "recursive" "submodules: recursive"
    else
        check "101.1 $n101: checkout fetches submodules recursively" "recursive" "missing"
    fi
done

fi

if phase_wanted 102; then
# ════════════════════════════════════════════════════════════════════════════
