    "$(jv122 "'|'.join([d[0]['rules'][0]['name'], d[0]['rules'][0]['then_add_label'][0], d[0]['rules'][0]['then_remove_label'][0], d[0]['rules'][0]['then_move_folder']])" "$OUT")"
